{"command":"cat > src/num.rs << 'EOF'
use serde_json::Value;
use std::cmp::Ordering;

// Exact decimal representation: value = sign * digits * 10^exp
// digits is a string of decimal digits without leading zeros ("0" for zero)
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Decimal {
    pub neg: bool,
    pub digits: String, // no leading/trailing zeros unless zero
    pub exp: i64,       // exponent applied to integer digits
}

pub fn parse_decimal_str(s: &str) -> Option<Decimal> {
    // s is serde_json number string e.g. 1e+2, -0.0, 123
    let mut mant = s;
    let mut exp_part: i64 = 0;
    if let Some(pos) = s.find(['e','E']) {
        mant = &s[..pos];
        exp_part = s[pos+1..].parse::<i64>().ok()?;
    }
    let neg = mant.starts_with('-');
    let mant = mant.trim_start_matches(['-','+']);
    let (int_part, frac_part) = match mant.split_once('.') {
        Some((a,b)) => (a,b),
        None => (mant,""),
    };
    let mut digits = String::new();
    digits.push_str(int_part);
    digits.push_str(frac_part);
    let mut exp = exp_part - frac_part.len() as i64;
    // strip leading zeros
    let stripped = digits.trim_start_matches('0');
    if stripped.is_empty() {
        return Some(Decimal{neg:false, digits:"0".into(), exp:0});
    }
    let mut d = stripped.to_string();
    // strip trailing zeros
    let trailing = d.len() - d.trim_end_matches('0').len();
    if trailing>0 { d.truncate(d.len()-trailing); exp += trailing as i64; }
    Some(Decimal{neg, digits:d, exp})
}

pub fn decimal_of(v: &Value) -> Option<Decimal> {
    match v {
        Value::Number(n) => parse_decimal_str(&n.to_string()),
        _ => None,
    }
}

fn cmp_abs(a: &Decimal, b: &Decimal) -> Ordering {
    if a.digits=="0" && b.digits=="0" { return Ordering::Equal; }
    if a.digits=="0" { return Ordering::Less; }
    if b.digits=="0" { return Ordering::Greater; }
    // magnitude: position of decimal point = exp + len(digits)
    let ma = a.exp + a.digits.len() as i64;
    let mb = b.exp + b.digits.len() as i64;
    if ma != mb { return ma.cmp(&mb); }
    // same magnitude, compare digits padded
    let maxlen = a.digits.len().max(b.digits.len());
    let mut da = a.digits.clone(); while da.len()<maxlen { da.push('0'); }
    let mut db = b.digits.clone(); while db.len()<maxlen { db.push('0'); }
    da.cmp(&db)
}

pub fn cmp_decimal(a: &Decimal, b: &Decimal) -> Ordering {
    match (a.neg, b.neg) {
        (true,false) => Ordering::Less,
        (false,true) => Ordering::Greater,
        (false,false) => cmp_abs(a,b),
        (true,true) => cmp_abs(b,a),
    }
}

pub fn decimal_eq(a:&Decimal,b:&Decimal)->bool{ cmp_decimal(a,b)==Ordering::Equal }
pub fn is_integer(d:&Decimal)->bool{
    if d.digits=="0" { return true; }
    d.exp>=0
}

impl Decimal {
    pub fn is_zero(&self)->bool{ self.digits=="0" }
    pub fn to_f64(&self)->f64{
        // reconstruct via string
        let s = format!("{}{}e{}", if self.neg{"-"}else{""}, self.digits, self.exp);
        s.parse::<f64>().unwrap_or(if self.neg{f64::NEG_INFINITY}else{f64::INFINITY})
    }
}

// Big integer helpers for multipleOf exact decimal check
// Represent decimals scaled to integers with a common exponent.
fn scaled_digits(d:&Decimal, target_exp:i64)->String{
    // value = digits *10^exp ; want integer digits *10^(exp-target_exp) assuming exp>=target
    let shift = d.exp - target_exp;
    let mut s = d.digits.clone();
    if shift>0 { for _ in 0..shift { s.push('0'); } }
    s
}

fn big_mod(digits:&str, divisor:&str)->String{
    // returns remainder string
    // divisor non-zero digits without leading zeros
    let mut rem: Vec<u8> = Vec::new(); // as digit bytes
    // implement long division remainder using integer as Vec<u8> big endian digits values
    // keep rem as digit vec numeric compare with divisor
    fn cmp_vec(a:&[u8], b:&[u8])->Ordering{
        let aa = { let mut i=0; while i<a.len() && a[i]==0 {i+=1;} &a[i..] };
        let bb = { let mut i=0; while i<b.len() && b[i]==0 {i+=1;} &b[i..] };
        if aa.len()!=bb.len(){ return aa.len().cmp(&bb.len()); }
        aa.cmp(bb)
    }
    fn sub_vec(a:&mut Vec<u8>, b:&[u8]){
        // a -= b assuming a>=b
        let mut borrow=0i16;
        let mut i=a.len(); let mut j=b.len();
        while i>0 { i-=1; let bv=if j>0 { j-=1; b[j] } else {0}; let v=a[i] as i16 - bv as i16 - borrow; if v<0 { a[i]=(v+10) as u8; borrow=1; } else { a[i]=v as u8; borrow=0; } }
    }
    let div_digits: Vec<u8> = divisor.bytes().map(|c|c-b'0').collect();
    for ch in digits.bytes() {
        rem.push(ch-b'0');
        // reduce
        while cmp_vec(&rem,&div_digits)!=Ordering::Less {
            sub_vec(&mut rem,&div_digits);
        }
    }
    // convert rem to string stripping leading zeros
    let s: String = rem.iter().map(|d|(d+b'0') as char).collect();
    let t=s.trim_start_matches('0');
    if t.is_empty(){"0".to_string()}else{t.to_string()}
}

pub fn is_multiple_of(value:&Decimal, divisor:&Decimal)->bool{
    if divisor.is_zero(){ return false; }
    if value.is_zero(){ return true; }
    // If both are large integers beyond u64, original crate falls back to f64-like behaviour;
    // we use exact math except emulate fallback for integer literals > u64:
    // Check exact decimal:
    let min_exp = value.exp.min(divisor.exp);
    // scaled integers might be huge for extreme exponents (e.g. 1e400). Cap: if shift enormous, use f64 method
    let shift_v = value.exp - min_exp;
    let shift_d = divisor.exp - min_exp;
    if shift_v>10000 || shift_d>10000 || value.digits.len() as i64+shift_v>10000 {
        let q = value.to_f64()/divisor.to_f64();
        if !q.is_finite(){ // 1e400/2 -> inf? to_f64 inf; then original valid for multipleOf 2.
            // Huge exponent cases: use exponent logic: if divisor power etc - fallback accept if... approximate: return true if q is inf and divisor !=0? mimic original (1e400 multiple of 2 was valid)
            return true;
        }
        let r = value.to_f64() % divisor.to_f64();
        return r==0.0 || (q - q.round()).abs() < 1e-9;
    }
    let a = scaled_digits(value, min_exp);
    let b = scaled_digits(divisor, min_exp);
    let a = a.trim_start_matches('0'); let b = b.trim_start_matches('0');
    if a.is_empty(){ return true; }
    big_mod(a,b)=="0"
}

pub fn value_is_integer(v:&Value)->bool{
    match v { Value::Number(_) => decimal_of(v).map(|d|is_integer(&d)).unwrap_or(false), _=>false }
}
pub fn value_is_number(v:&Value)->bool{ matches!(v, Value::Number(_)) }

pub fn json_eq(a:&Value,b:&Value)->bool{
    // numeric equality cross representation, containers structural
    match (a,b){
        (Value::Number(_),Value::Number(_))=>{
            match (decimal_of(a),decimal_of(b)){ (Some(x),Some(y))=>decimal_eq(&x,&y), _=>a==b }
        }
        (Value::Array(x),Value::Array(y))=> x.len()==y.len() && x.iter().zip(y.iter()).all(|(u,v)|json_eq(u,v)),
        (Value::Object(x),Value::Object(y))=>{
            if x.len()!=y.len(){return false;}
            x.iter().all(|(k,v)| y.get(k).map(|w|json_eq(v,w)).unwrap_or(false))
        }
        _=>a==b,
    }
}

pub fn format_json(v:&Value)->String{
    // serde_json Display for Value is compact serialization; numbers preserve repr (arbitrary_precision)
    v.to_string()
}
EOF
echo ok"}

