            if oh.chars().all(|c|c.is_ascii_digit())&&om.chars().all(|c|c.is_ascii_digit()){
                let ohi:i64=oh.parse().unwrap(); let omi:i64=om.parse().unwrap();
                return ohi<=23&&omi<=59;
            }
        }
        false
    } else {false}
}

pub fn valid_datetime(s:&str)->bool{
    // locate T or t or space
    let mut idx=None;
    for (i,c) in s.char_indices(){ if c=='T'||c=='t'||c==' ' {idx=Some(i); break;}}
    let Some(i)=idx else{return false};
    let date=&s[..i]; let time=&s[i+1..];
    if time.is_empty(){return false;}
    if !valid_date(date){return false;}
    // date-time requires offset
    // validate time and require Z/offset present
    // rebuild check: valid_time and time has Z or offset at end
    if !valid_time(time){return false;}
    // valid_time allows no offset; require offset for date-time if original spec: check trailing
    let has_offset = time.ends_with('Z')||time.ends_with('z')||{
        let bytes=time.as_bytes();
        bytes.len()>=6 && (bytes[bytes.len()-6]==b'+'||bytes[bytes.len()-6]==b'-')
    };
    if !has_offset{return false;}
    // separator must be T/t ; space might be allowed by RFC3339 as separator by agreement - crate may reject space. check: we allow? We'll require T/t
    let sep=s.as_bytes()[i]; if sep!=b'T'&&sep!=b't'{return false;}
    true
}

fn valid_ipv4(s:&str)->bool{
    if Ipv4Addr::from_str(s).is_err(){return false;}
    // reject leading zeros in octets (Rust parser already rejects? Python-style; std rejects leading zeros)
    for part in s.split('.'){
        if part.len()>1 && part.starts_with('0'){return false;}
    }
    true
}

fn valid_uuid(s:&str)->bool{
    let parts:Vec<&str>=s.split('-').collect();
    if parts.len()!=5{return false;}
    let lens=[8,4,4,4,12];
    for (p,l) in parts.iter().zip(lens){ if p.len()!=l||!p.chars().all(|c|c.is_ascii_hexdigit()){return false;}}
    true
}

fn valid_hostname(s:&str,idn:bool)->bool{
    if s.is_empty()||s.len()>253{return false;}
    let ss=if s.ends_with('.'){&s[..s.len()-1]}else{s};
    if ss.is_empty(){return false;}
    for label in ss.split('.'){
        if label.is_empty()||label.len()>63{return false;}
        // label length in chars? spec bytes; check char count and utf8 len
        if label.starts_with('-')||label.ends_with('-'){return false;}
        for c in label.chars(){
            if idn { if !(c.is_alphanumeric()||c=='-') {return false;} }
            else if !(c.is_ascii_alphanumeric()||c=='-'){return false;}
        }
    }
    true
}

fn valid_email(s:&str,idn:bool)->bool{
    // must have exactly one @ (allow quoted local later simplistic)
    let mut parts=s.rsplitn(2,'@');
    let domain=parts.next().unwrap_or(""); let local_opt=parts.next();
    if local_opt.is_none(){return false;}
    let local=local_opt.unwrap();
    if local.is_empty()||domain.is_empty(){return false;}
    // no spaces / controls
    if s.chars().any(|c|c.is_control()||c==' '){return false;}
    // local: dot atom
    if local.starts_with('.')||local.ends_with('.')||local.contains(".."){return false;}
    for c in local.chars(){
        if idn { if !(c.is_alphanumeric()||"!#$%&'*+-/=?^_`{|}~.".contains(c)) {return false;} }
        else if !(c.is_ascii_alphanumeric()||"!#$%&'*+-/=?^_`{|}~.".contains(c)){return false;}
    }
    // domain: hostname or [ip]
    if domain.starts_with('[')&&domain.ends_with(']'){
        let inside=&domain[1..domain.len()-1];
        return Ipv4Addr::from_str(inside).is_ok()||Ipv6Addr::from_str(inside).is_ok();
    }
    // domain must contain? a@b passed, single label allowed
    valid_hostname(domain,idn)
}

fn valid_uri_chars(s:&str,iri:bool)->bool{
    // validate percent escapes & characters
    let bytes=s.as_bytes(); let mut i=0;
    while i<bytes.len(){
        let c=s[i..].chars().next().unwrap();
        if c=='%'{
            if i+2>=s.len()||!s[i+1..i+3].chars().all(|x|x.is_ascii_hexdigit()){return false;}
            i+=3; continue;
        }
        if c.is_control()||c==' '||c=='"'||c=='<'||c=='>'||c=='\\'||c=='^'||c=='`'||c=='{'||c=='}'||c=='|'||c=='\u{7f}'{return false;}
        if !iri && !c.is_ascii(){return false;}
        i+=c.len_utf8();
    }
    true
}

fn valid_uri(s:&str,iri:bool,absolute:bool)->bool{
    if s.is_empty(){return !absolute;}
    if !valid_uri_chars(s,iri){return false;}
    if absolute {
        // scheme required: ALPHA *(ALPHA DIGIT + - .) ":"
        let Some(colon)=s.find(':') else{return false};
        let scheme=&s[..colon];
        if scheme.is_empty()||!scheme.chars().next().unwrap().is_ascii_alphabetic(){return false;}
        if !scheme.chars().all(|c|c.is_ascii_alphanumeric()||c=='+'||c=='-'||c=='.'){return false;}
        // after colon must be non-empty? uri can be scheme: (path)
        if colon==s.len()-1{ /* scheme: with empty path - crate might reject? */ }
        true
    } else {
        // if colon in first segment, scheme must be valid
        if let Some(colon)=s.find(':'){
            let first_delim = s.find(['/', '?', '#']).unwrap_or(s.len());
            if colon<first_delim {
                let scheme=&s[..colon];
                if scheme.is_empty()||!scheme.chars().next().unwrap().is_ascii_alphabetic()||!scheme.chars().all(|c|c.is_ascii_alphanumeric()||c=='+'||c=='-'||c=='.'){return false;}
            }
        }
        true
    }
}

pub fn valid_json_pointer(s:&str)->bool{
    if s.is_empty(){return true;}
    if !s.starts_with('/'){return false;}
    // validate ~ escapes
    let mut chars=s.chars().peekable();
    // iterate
    let mut iter=s.chars();
    while let Some(c)=iter.next(){
        if c=='~'{
            match iter.next(){ Some('0')|Some('1')=>{}, _=>return false }
        }
    }
    let _=chars;
    true
}

fn valid_rel_pointer(s:&str)->bool{
    if s.is_empty(){return false;}
    // ( "0" / [1-9] digits ) ( "#" / json-pointer )
    let bytes=s.as_bytes();
    let mut i=0;
    if !bytes[0].is_ascii_digit(){return false;}
    if bytes[0]==b'0'{ i=1; } else { while i<bytes.len()&&bytes[i].is_ascii_digit(){i+=1;} }
    let rest=&s[i..];
    if rest.is_empty(){return true;}
    if rest=="#" {return true;}
    valid_json_pointer(rest)
}

pub fn valid_duration(s:&str)->bool{
    // ISO8601: P ... 
    if !s.starts_with('P'){return false;}
    let rest=&s[1..]; if rest.is_empty(){return false;}
    // regex approach
    // We'll parse manually
    // Components: either nW alone, or date part + optional time part
    // Check using regex crate
    let re = regex::Regex::new(r"^(?:\d+(?:[.,]\d+)?W|(?:(?:\d+(?:[.,]\d+)?Y)?(?:\d+(?:[.,]\d+)?M)?(?:\d+(?:[.,]\d+)?D)?)(?:T(?:\d+(?:[.,]\d+)?H)?(?:\d+(?:[.,]\d+)?M)?(?:\d+(?:[.,]\d+)?S)?)?)$").unwrap();
    if !re.is_match(rest){return false;}
    // Must have at least one component and if T present, at least one time component
    if rest=="T" {return false;}
    // If contains T, ensure something after T
    if let Some(pos)=rest.find('T'){ if pos==rest.len()-1 {return false;} }
    // Rest must contain a digit
    if !rest.chars().any(|c|c.is_ascii_digit()){return false;}
    // P with date part empty but T ... okay if handled
    // Also "P" handled. Ensure not just "T..." is captured, rest after P can't start??? valid "PT0S"
    true
}

pub fn valid_uri_template(s:&str)->bool{
    let mut chars=s.chars().peekable();
    let mut in_expr=false;
    let mut expr=String::new();
    while let Some(c)=chars.next(){
        if in_expr {
            if c=='}'{
                if !valid_template_expr(&expr){return false;}
                expr.clear(); in_expr=false;
            } else if c=='{' {return false;} else {expr.push(c);}
        } else {
            if c=='{'{in_expr=true;}
            else if c=='}'{return false;}
        }
    }
    !in_expr
}
fn valid_template_expr(expr:&str)->bool{
    if expr.is_empty(){return false;}
    let mut e=expr;
    let first=e.chars().next().unwrap();
    if "+#./;?&=,!@|".contains(first){ e=&e[1..]; }
    if e.is_empty(){return false;}
    for part in e.split(','){
        if part.is_empty(){return false;}
        let mut p=part;
        if p.ends_with('*'){ p=&p[..p.len()-1]; }
        if let Some(colon)=p.find(':'){
            let (name,num)=p.split_at(colon);
            if name.is_empty()||!num[1..].chars().all(|c|c.is_ascii_digit())||num.len()==1{return false;}
            p=name;
        }
        if p.is_empty(){return false;}
        for c in p.chars(){ if !(c.is_ascii_alphanumeric()||c=='_'||c=='.'||c=='%'){ 
            // % must be hex triplet
            if c=='%' { continue; } return false; } }
        // validate %-escapes in names loosely
        let bytes=p.as_bytes(); let mut i=0; while i<bytes.len(){ if bytes[i]==b'%' { if i+2>=bytes.len()||!p[i+1..i+3].chars().all(|x|x.is_ascii_hexdigit()){return false;} i+=3;} else {i+=1;}}
    }
    true
}
