    for (i,c) in s.char_indices(){
        let ok = match c {
            'A'..='Z'|'a'..='z'|'0'..='9'|'-'|'.'|'_'|'~'|':'|'/'|'?'|'#'|'['|']'|'@'|'!'|'$'|'&'|'\''|'('|')'|'*'|'+'|','|';'|'='|'%' => true,
            _ => false,
        };
        if !ok {
            return Err(format!("unexpected character at index {}", i));
        }
        // percent encoding validated later? We'll check in following loop
        let _ = i;
    }
    // Validate percent triples: if invalid, fluent-uri may report unexpected... We'll probe later; approximate
    let bytes=s.as_bytes(); let mut i=0;
    while i<bytes.len(){
        if bytes[i]==b'%'{
            if i+2>=bytes.len() || !(bytes[i+1] as char).is_ascii_hexdigit() || !(bytes[i+2] as char).is_ascii_hexdigit(){
                // Might be handled as unexpected character at percent? We'll treat as unexpected character at index of %
                return Err(format!("unexpected character at index {}", i));
            }
            i+=3;
        } else { i+=1; }
    }
    Ok(())
}

pub fn validate_uri_ref_err(s:&str)->Option<String>{
    match validate_uri_ref(s){ Ok(())=>None, Err(e)=>Some(format!("Invalid URI reference '{}': {}", s, e))}
}

// split fragment (after first #)
pub fn split_fragment(uri:&str)->(&str,&str){
    match uri.find('#'){ Some(i)=>( &uri[..i], &uri[i+1..]), None=>(uri,"")}
}
pub fn without_fragment(uri:&str)->String{ split_fragment(uri).0.to_string() }
pub fn fragment(uri:&str)->String{ split_fragment(uri).1.to_string() }

pub fn has_scheme(uri:&str)->bool{
    // scheme present before any /?#
    if let Some(colon)=uri.find(':'){
        let delim=uri.find(['/', '?', '#']).unwrap_or(uri.len());
        if colon<delim && colon>0 {
            let sch=&uri[..colon];
            return sch.chars().next().unwrap().is_ascii_alphabetic() && sch.chars().all(|c|c.is_ascii_alphanumeric()||c=='+'||c=='-'||c=='.');
        }
    }
    false
}
pub fn scheme_of(uri:&str)->Option<String>{
    if has_scheme(uri){ uri.find(':').map(|i|uri[..i].to_ascii_lowercase()) } else {None}
}

// RFC3986 5.3 resolution
fn remove_dot_segments(path:&str)->String{
    let mut input=path.to_string();
    let mut output=String::new();
    while !input.is_empty(){
        if input.starts_with("../"){ input=input[3..].to_string(); }
        else if input.starts_with("./"){ input=input[2..].to_string(); }
        else if input.starts_with("/./"){ input=format!("/{}", &input[3..]); }
        else if input=="/."{ input="/".to_string(); }
        else if input.starts_with("/../"){ input=format!("/{}", &input[4..]); // pop last segment from output
            if let Some(pos)=output.rfind('/'){ output.truncate(pos); }
        }
        else if input=="/.."{ input="/".to_string(); if let Some(pos)=output.rfind('/'){ output.truncate(pos); } }
        else if input=="."||input==".."{ input.clear(); }
        else {
            // move first segment
            let start=if input.starts_with('/') {1}else{0};
            let end=match input[start..].find('/'){ Some(p)=>start+p, None=>input.len()};
            output.push_str(&input[..end]);
            input=input[end..].to_string();
        }
    }
    output
}

#[derive(Debug,Clone,PartialEq)]
struct Parts{ scheme:Option<String>, authority:Option<String>, path:String, query:Option<String>, fragment:Option<String> }

fn parse_parts(uri:&str)->Parts{
    let (no_frag, frag) = match uri.find('#'){ Some(i)=>( &uri[..i], Some(uri[i+1..].to_string())), None=>(uri,None)};
    let mut rest=no_frag;
    let mut scheme=None;
    if has_scheme(rest){
        let colon=rest.find(':').unwrap(); scheme=Some(rest[..colon].to_string()); rest=&rest[colon+1..];
    }
    let mut authority=None;
    let mut after_authority=rest;
    if rest.starts_with("//"){
        let after=&rest[2..];
        let end=after.find(['/', '?']).unwrap_or(after.len());
        authority=Some(after[..end].to_string());
        after_authority=&after[end..];
    }
    let (path, query)=match after_authority.find('?'){ Some(i)=>(after_authority[..i].to_string(), Some(after_authority[i+1..].to_string())), None=>(after_authority.to_string(),None)};
    Parts{scheme,authority,path,query,fragment:frag}
}

fn build_parts(p:&Parts)->String{
    let mut out=String::new();
    if let Some(s)=&p.scheme{ out.push_str(s); out.push(':'); }
    if let Some(a)=&p.authority{ out.push_str("//"); out.push_str(a); }
    out.push_str(&p.path);
    if let Some(q)=&p.query{ out.push('?'); out.push_str(q); }
    if let Some(f)=&p.fragment{ out.push('#'); out.push_str(f); }
    out
}

pub fn resolve_uri(base:&str, reference:&str)->String{
    // If reference has same scheme ??? RFC strict
    let b=parse_parts(base);
    let r=parse_parts(reference);
    // Reference fragment handling: result fragment = r.fragment
    if reference.is_empty(){
        let mut t=b.clone(); t.fragment=r.fragment.clone(); // "" has no fragment? Actually empty ref: fragment undefined -> keep? In JSON Schema "" resolves to base without fragment?
        // RFC: empty reference inherits base fragment? but schema "" should be current doc (without fragment)
        t.fragment=None;
        if r.fragment.is_some(){ t.fragment=r.fragment.clone(); }
        return build_parts(&t);
    }
    if let Some(hash)=reference.find('#'){
        if hash==0{
            // same document with fragment
            let mut t=b.clone(); t.fragment=r.fragment.clone(); return build_parts(&t);
        }
    }
    let mut t=Parts{scheme:None,authority:None,path:String::new(),query:None,fragment:r.fragment.clone()};
    if r.scheme.is_some(){
        t.scheme=r.scheme.clone(); t.authority=r.authority.clone(); t.path=remove_dot_segments(&r.path); t.query=r.query.clone();
    } else {
        if r.authority.is_some(){
            t.authority=r.authority.clone(); t.path=remove_dot_segments(&r.path); t.query=r.query.clone();
        } else {
            if r.path.is_empty(){
                t.path=b.path.clone();
                t.query=if r.query.is_some(){r.query.clone()}else{b.query.clone()};
            } else {
                if r.path.starts_with('/'){
                    t.path=remove_dot_segments(&r.path);
                } else {
                    // merge
                    let merged=if b.authority.is_some() && b.path.is_empty(){
                        format!("/{}", r.path)
                    } else {
                        match b.path.rfind('/'){ Some(idx)=>format!("{}{}", &b.path[..=idx], r.path), None=>r.path.clone()}
                    };
                    t.path=remove_dot_segments(&merged);
                }
                t.query=r.query.clone();
            }
            t.authority=b.authority.clone();
        }
        t.scheme=b.scheme.clone();
    }
    // normalize scheme & authority case
    if let Some(s)=&mut t.scheme{ *s=s.to_ascii_lowercase(); }
    if let Some(a)=&mut t.authority{
        // lowercase host part (after @, before : port or [)
        // simple: lowercase except percent/userinfo case? lowercase whole authority except userinfo
        let (userinfo, hostport)=match a.rfind('@'){ Some(i)=>(Some(a[..=i].to_string()), a[i+1..].to_string()), None=>(None,a.clone())};
        let lowered=hostport.to_ascii_lowercase();
        *a=format!("{}{}", userinfo.unwrap_or_default(), lowered);
    }
    build_parts(&t)
}

pub fn escape_pointer_token(s:&str)->String{ s.replace('~',"~0").replace('/',"~1") }
pub fn unescape_pointer_token(s:&str)->String{ s.replace("~1","/").replace("~0","~") }

pub fn pointer_escape_join(base:&str, token:&str)->String{
    format!("{}/{}", base, escape_pointer_token(token))
}

// Percent-decoding for fragment pointer etc.
pub fn percent_decode(s:&str)->String{
    let bytes=s.as_bytes(); let mut out=Vec::new(); let mut i=0;
    while i<bytes.len(){
        if bytes[i]==b'%' && i+2<bytes.len() && (bytes[i+1] as char).is_ascii_hexdigit() && (bytes[i+2] as char).is_ascii_hexdigit(){
            let hex=&s[i+1..i+3]; out.push(u8::from_str_radix(hex,16).unwrap()); i+=3;
        } else { out.push(bytes[i]); i+=1; }
    }
    String::from_utf8_lossy(&out).to_string()
}

pub fn file_path_to_uri(path:&str)->String{
    // path is absolute (caller ensures)
    let mut out=String::from("file://");
    for seg in path.split('/'){
        if seg.is_empty(){ out.push('/'); continue; }
        out.push_str(&percent_encode_segment(seg));
        out.push('/');
    }
    // we pushed trailing slash after each seg including file; fix: reconstruct
    // Simpler: rebuild
    let mut result=String::from("file://");
    // path starts with /
    for (idx, byte) in path.bytes().enumerate(){
        let c=byte as char;
        if c=='/' { result.push('/'); }
        else if c.is_ascii_alphanumeric() || "-._~!$&'()*+,;=:@".contains(c) { result.push(c); }
        else {
            // encode byte-wise using raw bytes of path string (UTF-8)
            result.push_str(&format!("%{:02X}", byte));
            let _=idx;
        }
    }
    result
}

fn percent_encode_segment(seg:&str)->String{
    let mut out=String::new();
    for &byte in seg.as_bytes(){
        let c=byte as char;
        if c.is_ascii_alphanumeric() || "-._~!$&'()*+,;=:@".contains(c){ out.push(c);} else { out.push_str(&format!("%{:02X}",byte)); }
    }
    out
}

pub fn uri_to_file_path(uri:&str)->Option<String>{
    let p=parse_parts(uri);
    if p.scheme.as_deref()!=Some("file"){return None;}
    // authority must be empty or localhost
    if let Some(a)=&p.authority{ if !a.is_empty() && a!="localhost"{ /* still treat as path? */ } }
    Some(percent_decode(&p.path))
}

pub type RegistryDocs = BTreeMap<String, usize>;
