// ---------- Retrieval ----------
#[derive(Clone, Debug)]
pub struct RetrieverConfig {
    pub connect_timeout: Option<Duration>,
    pub timeout: Option<Duration>,
    pub insecure: bool,
}
impl Default for RetrieverConfig { fn default()->Self{Self{connect_timeout:None,timeout:None,insecure:false}} }

// Error string already is the retriever error fragment (after "retrieving it failed: ")
pub fn retrieve_resource(uri_no_frag:&str, cfg:&RetrieverConfig)->Result<Value,String>{
    // scheme detection
    match uri::scheme_of(uri_no_frag){
        None=>{ return Err("Unknown scheme json-schema".to_string()); }
        Some(sch) if sch=="file"=>{
            let path = uri::uri_to_file_path(uri_no_frag).ok_or_else(||"No such file or directory (os error 2)".to_string())?;
            let data = std::fs::read(&path).map_err(|e| e.to_string())?;
            let v:Value = serde_json::from_slice(&data).map_err(|e| e.to_string())?;
            return Ok(v);
        }
        Some(sch) if sch=="http" || sch=="https"=>{
            return crate::http::fetch_json(uri_no_frag, cfg);
        }
        Some(sch)=>{
            return Err(format!("Unknown scheme {}", sch));
        }
    }
}

pub fn resource_error(uri_display:&str, err:&str)->String{
    format!("Resource '{}' is not present in a registry and retrieving it failed: {}", uri_display, err)
}

// ---------- Registry ----------
pub type Pointer = Vec<String>;

pub fn pointer_to_string(ptr:&Pointer)->String{
    let mut s=String::new();
    for t in ptr { s.push('/'); s.push_str(&uri::escape_pointer_token(t)); }
    s
}
pub fn parse_pointer_fragment(frag:&str)->Option<Pointer>{
    if frag.is_empty(){ return Some(vec![]); }
    if !frag.starts_with('/'){ return None; }
    let decoded = uri::percent_decode(frag);
    let mut out=Vec::new();
    for part in decoded.split('/').skip(1){ out.push(uri::unescape_pointer_token(part)); }
    Some(out)
}

#[derive(Clone,Debug)]
pub struct Doc {
    pub value: Value,
    pub base_uri: String, // retrieval uri without fragment
    pub draft: Draft,
}

#[derive(Clone,Debug,PartialEq,Eq,Hash)]
pub struct NodeKey{ pub doc:usize, pub ptr:Pointer }

#[derive(Clone,Debug)]
pub struct CNode {
    pub doc: usize,
    pub ptr: Pointer,
    pub base_uri: String,    // base in effect for parent (before own $id)
    pub loc_uri: String,     // resource uri for location (before own $id)
    pub loc_root: Pointer,   // pointer of resource root in doc
    pub draft: Draft,
}
impl CNode {
    pub fn key(&self)->NodeKey{ NodeKey{doc:self.doc, ptr:self.ptr.clone()} }
}

pub struct Registry {
    pub docs: Vec<Doc>,
    pub by_uri: HashMap<String, usize>, // doc base uri -> doc idx
    pub id_resources: HashMap<String, (usize, Pointer)>, // absolute uri no frag -> node
    pub anchors: HashMap<String, (usize, Pointer)>, // absolute uri with #anchor -> node
    pub dynamic_anchors: HashMap<String, (usize, Pointer)>, // uri with #anchor -> node
    pub cfg: RetrieverConfig,
}

impl Registry {
    pub fn new(cfg:RetrieverConfig)->Self{ Self{docs:vec![],by_uri:HashMap::new(),id_resources:HashMap::new(),anchors:HashMap::new(),dynamic_anchors:HashMap::new(),cfg} }
    pub fn doc_value(&self, doc:usize)->&Value{ &self.docs[doc].value }
    pub fn get_node_value(&self, doc:usize, ptr:&Pointer)->Option<&Value>{
        let mut cur=&self.docs[doc].value;
        for tok in ptr {
            match cur {
                Value::Object(m)=>{ cur=m.get(tok)?; }
                Value::Array(a)=>{ let idx:usize=tok.parse().ok()?; cur=a.get(idx)?; }
                _=>return None,
            }
        }
        Some(cur)
    }

    // add a document, index its resources, recursively retrieve external references ($ref targets)
    pub fn add_document(&mut self, base_uri:String, value:Value, draft:Draft)->Result<usize,String>{
        let base_no_frag = uri::without_fragment(&base_uri);
        if let Some(&idx)=self.by_uri.get(&base_no_frag){ return Ok(idx); }
        let idx=self.docs.len();
        self.docs.push(Doc{value, base_uri:base_no_frag.clone(), draft});
        self.by_uri.insert(base_no_frag.clone(), idx);
        // index resources
        self.index_document(idx)?;
        // scan external refs eagerly
        let refs = self.collect_ref_uris(idx);
        for abs_uri in refs {
            let nofrag = uri::without_fragment(&abs_uri);
            if nofrag.is_empty(){ continue; }
            if self.by_uri.contains_key(&nofrag) || self.id_resources.contains_key(&nofrag){ continue; }
            // Also if it refers to current doc base etc.
            // retrieve
            let doc_draft = self.docs[idx].draft;
            match retrieve_resource(&nofrag, &self.cfg){
                Ok(v)=>{
                    // determine draft for external doc
                    let ext_draft = declared_draft(&v).unwrap_or(doc_draft);
                    self.add_document(nofrag.clone(), v, ext_draft)?;
                }
                Err(e)=>{
                    return Err(resource_error(&nofrag,&e));
                }
            }
        }
        Ok(idx)
    }

    fn index_document(&mut self, idx:usize)->Result<(),String>{
        // Walk schema nodes collecting $id/$anchor/$dynamicAnchor
        // We work on a cloned list of (pointer, base_uri) to avoid borrow issues
        let mut to_visit: Vec<(Pointer,String)> = vec![(vec![], self.docs[idx].base_uri.clone())];
        // We'll do DFS using stack, collecting nodes
        // Need deterministic order: use queue in order of traversal (sorted keys because serde_json BTree)
        let mut visited: Vec<(Pointer,String)> = Vec::new();
        while let Some((ptr,base)) = to_visit.pop() {
            // We want pre-order; use visited collection then process; children pushed in reverse
            visited.push((ptr.clone(), base.clone()));
            let node = match self.get_node_value(idx,&ptr){ Some(v)=>v.clone(), None=>continue };
            let mut cur_base = base.clone();
            if let Value::Object(obj)=&node {
                // if this node has $id -> cur base changes for children, but node itself registration handled in processing
                if let Some(idv)=obj.get("$id").and_then(|v|v.as_str()){
                    if let Some(err)=uri::validate_uri_ref_err(idv){ return Err(err); }
                    cur_base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                } else if self.docs[idx].draft==Draft::D4 {
                    if let Some(idv)=obj.get("id").and_then(|v|v.as_str()){
                        if let Some(err)=uri::validate_uri_ref_err(idv){ return Err(err); }
                        cur_base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                    }
                }
                // children
                let mut child_ptrs: Vec<Pointer> = Vec::new();
                collect_schema_children(obj, &ptr, &mut child_ptrs);
                // push in reverse so first child processed first (stack)
                for cp in child_ptrs.into_iter().rev(){
                    to_visit.push((cp, cur_base.clone()));
                }
            } else if let Value::Array(_)=&node {
                // shouldn't happen as schema child except arrays already expanded in collect_schema_children
            }
        }
        // Now register in visited order
        for (ptr, base) in visited {
            let node = match self.get_node_value(idx,&ptr){ Some(v)=>v.clone(), None=>continue };
            if let Value::Object(obj)=&node {
                let mut effective_base = base.clone();
                if let Some(idv)=obj.get("$id").and_then(|v|v.as_str()){
                    let resolved = uri::resolve_uri(&base, idv);
                    let nofrag = uri::without_fragment(&resolved);
                    self.id_resources.insert(nofrag.clone(), (idx, ptr.clone()));
                    effective_base = nofrag;
                } else if self.docs[idx].draft==Draft::D4 {
                    if let Some(idv)=obj.get("id").and_then(|v|v.as_str()){
                        let resolved = uri::resolve_uri(&base, idv);
                        let nofrag = uri::without_fragment(&resolved);
                        self.id_resources.insert(nofrag.clone(), (idx, ptr.clone()));
                        effective_base = nofrag;
                    }
                }
                if let Some(av)=obj.get("$anchor").and_then(|v|v.as_str()){
                    let key = format!("{}#{}", effective_base, av);
                    self.anchors.insert(key, (idx, ptr.clone()));
                }
                if let Some(av)=obj.get("$dynamicAnchor").and_then(|v|v.as_str()){
                    let key = format!("{}#{}", effective_base, av);
                    self.anchors.insert(key.clone(), (idx, ptr.clone()));
                    self.dynamic_anchors.insert(key, (idx, ptr.clone()));
                }
                if let Some(Value::Bool(true))=obj.get("$recursiveAnchor"){
                    // recursive anchor with empty name? registers dynamic anchor "" for doc base
                    // store under base# (empty)
                    // not needed commonly
                }
            }
        }
        Ok(())
    }

    fn collect_ref_uris(&self, idx:usize)->Vec<String>{
        let mut out=Vec::new();
        let mut stack: Vec<Pointer>=vec![vec![]];
        while let Some(ptr)=stack.pop(){
            let node=match self.get_node_value(idx,&ptr){Some(v)=>v,None=>continue};
            if let Value::Object(obj)=node {
                // base for this node
                // compute base by traversing ancestors quickly (expensive but ok for small schemas)
                let base = self.base_for_pointer(idx,&ptr);
                for key in ["$ref","$dynamicRef","$recursiveRef"]{
                    if let Some(rv)=obj.get(key).and_then(|v|v.as_str()){
                        // validate URI ref
                        // errors will surface later; here collect
                        let resolved = uri::resolve_uri(&base, rv);
                        out.push(resolved);
                    }
                }
                let mut child_ptrs=Vec::new();
                collect_schema_children(obj,&ptr,&mut child_ptrs);
                for cp in child_ptrs.into_iter().rev(){ stack.push(cp); }
            }
        }
        out
    }

    pub fn base_for_pointer(&self, idx:usize, target:&Pointer)->String{
        // traverse ancestors from root to target (exclusive of target own $id? includes parents)
        let mut base=self.docs[idx].base_uri.clone();
        let mut cur_ptr:Pointer=vec![];
        // for each ancestor including target node itself? For resolving $ref inside target, we need base after target's own $id.
        // This function returns base after applying $ids along path including target.
        for depth in 0..=target.len(){
            let p:Pointer=target[..depth].to_vec();
            if let Some(Value::Object(obj))=self.get_node_value(idx,&p){
                if let Some(idv)=obj.get("$id").and_then(|v|v.as_str()){
                    base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                } else if self.docs[idx].draft==Draft::D4 {
                    if let Some(idv)=obj.get("id").and_then(|v|v.as_str()){
                        base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                    }
                }
            }
            cur_ptr=p;
        }
        let _=cur_ptr;
        base
    }

    pub fn loc_context_for(&self, idx:usize, target:&Pointer)->(String,String,Pointer){
        // returns (base_uri_parent_before_target_id, loc_uri, loc_root)
        // Walk ancestors up to parent
        let mut base=self.docs[idx].base_uri.clone();
        let mut loc_uri=self.docs[idx].base_uri.clone();
        let mut loc_root:Pointer=vec![];
        for depth in 0..target.len(){
            let p:Pointer=target[..depth].to_vec();
            if let Some(Value::Object(obj))=self.get_node_value(idx,&p){
                if let Some(idv)=obj.get("$id").and_then(|v|v.as_str()){
                    base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                    loc_uri=base.clone(); loc_root=p.clone();
                } else if self.docs[idx].draft==Draft::D4 {
                    if let Some(idv)=obj.get("id").and_then(|v|v.as_str()){
                        base = uri::without_fragment(&uri::resolve_uri(&base, idv));
                        loc_uri=base.clone(); loc_root=p.clone();
                    }
                }
            }
        }
        (base, loc_uri, loc_root)
    }

    // Resolve a reference string in context of a node.
    // Returns (CNode for target, is_dynamic_anchor_target?)
    pub fn resolve_ref(&self, from:&CNode, ref_str:&str, dynamic_scope:&[DynamicFrame])->Result<ResolvedTarget,String>{
        // validate uri ref
        if let Some(err)=uri::validate_uri_ref_err(ref_str){ return Err(err); }
        let from_base = self.effective_base(from);
        let resolved = uri::resolve_uri(&from_base, ref_str);
        let (no_frag, frag) = (uri::without_fragment(&resolved), uri::fragment(&resolved));
        // find doc
        // dynamic handling done by caller for $dynamicRef/$recursiveRef
        self.resolve_resolved_uri(&resolved, &nofrag, &frag, Some(from))
    }

    pub fn effective_base(&self, node:&CNode)->String{
        // base after own $id
        self.base_for_pointer(node.doc, &node.ptr)
    }

    pub fn resolve_resolved_uri(&self, _resolved:&str, nofrag:&str, frag:&str, _from:Option<&CNode>)->Result<ResolvedTarget,String>{
        // locate doc / subresource
        let (doc_idx, target_ptr, anchor_root): (usize, Pointer, bool) = if frag.is_empty() || frag=="" {
            // whole resource
            if let Some(&d)=self.by_uri.get(nofrag){
                (d, vec![], false)
            } else if let Some((d,p))=self.id_resources.get(nofrag){
                (*d, p.clone(), false)
            } else if nofrag.is_empty(){
                // shouldn't happen
                return Err("Pointer '' does not exist".to_string());
            } else {
                // resource not present: retrieval error will have been raised in add_document scanning,
                // but for refs created dynamically (dynamic etc) produce that error
                // Check if there's a doc with this base? else
                return Err(resource_error(nofrag, "No such file or directory (os error 2)"));
            }
        } else if frag.starts_with('/') {
            // pointer
            let doc_idx = if let Some(&d)=self.by_uri.get(nofrag){ d } else if let Some((d,_))=self.id_resources.get(nofrag){ *d } else {
                return Err(resource_error(nofrag, "No such file or directory (os error 2)"));
            };
            // if id_resources points to a subresource root, pointer is relative to that root? In referencing, URI with pointer fragment resolves from document root.
            // For pointer we need document root pointer navigation: use doc's JSON root
            let ptr = parse_pointer_fragment(frag).unwrap_or_default();
            // check existence
            if self.get_node_value(doc_idx,&ptr).is_none(){
                return Err(format!("Pointer '{}' does not exist", frag));
            }
            (doc_idx, ptr, false)
        } else {
            // plain name anchor
            let key = format!("{}#{}", nofrag, frag);
            if let Some((d,p))=self.anchors.get(&key){
                (*d, p.clone(), true)
            } else {
                return Err(format!("Anchor '{}' does not exist", frag));
            }
        };
        // Build CNode
        let (parent_base, loc_uri, loc_root) = self.loc_context_for(doc_idx,&target_ptr);
        let (loc_uri2, loc_root2) = if anchor_root { (nofrag.to_string(), target_ptr.clone()) } else { (loc_uri, loc_root) };
        // doc draft
        let draft = self.docs[doc_idx].draft;
        let cnode = CNode{doc:doc_idx, ptr:target_ptr, base_uri:parent_base, loc_uri:loc_uri2, loc_root:loc_root2, draft};
        Ok(ResolvedTarget{cnode, fragment:frag.to_string()})
    }
}

#[derive(Clone,Debug)]
pub struct ResolvedTarget{ pub cnode:CNode, pub fragment:String }

#[derive(Clone,Debug)]
pub struct DynamicFrame {
    pub node: CNode, // schema node entered via a ref (the outermost ref target for this scope)
    pub name_uri: String, // dynamic anchor uri (base#name)?? We'll store anchor map info
}

pub fn declared_draft(v:&Value)->Option<Draft>{
    if let Value::Object(o)=v{
        if let Some(s)=o.get("$schema").and_then(|x|x.as_str()){
            return detect_known_draft(s);
        }
    }
    None
}

pub fn schema_children_of(obj:&Map<String,Value>, ptr:&Pointer)->Vec<Pointer>{
    let mut out=Vec::new(); collect_schema_children(obj,ptr,&mut out); out
}

fn collect_schema_children(obj:&Map<String,Value>, ptr:&Pointer, out:&mut Vec<Pointer>){
    // Deterministic order: iterate keys (BTree sorted)
    for (k,v) in obj.iter(){
        match k.as_str(){
            "properties"|"patternProperties"|"dependentSchemas"|"$defs"|"definitions"=> {
                if let Value::Object(m)=v{ for (name,_) in m { let mut p=ptr.clone(); p.push(k.clone()); p.push(name.clone()); out.push(p); } }
            }
            "dependencies"=>{
                if let Value::Object(m)=v{ for (name,sub) in m { if matches!(sub, Value::Object(_) | Value::Bool(_)) { let mut p=ptr.clone(); p.push(k.clone()); p.push(name.clone()); out.push(p); } } }
            }
            "items"=>{
                match v {
                    Value::Array(a)=>{ for i in 0..a.len(){ let mut p=ptr.clone(); p.push(k.clone()); p.push(i.to_string()); out.push(p);} }
                    Value::Object(_)|Value::Bool(_)=>{ let mut p=ptr.clone(); p.push(k.clone()); out.push(p); }
                    _=>{}
                }
            }
            "prefixItems"|"allOf"|"anyOf"|"oneOf"=>{
                if let Value::Array(a)=v{ for i in 0..a.len(){ let mut p=ptr.clone(); p.push(k.clone()); p.push(i.to_string()); out.push(p);} }
            }
            "additionalProperties"|"additionalItems"|"contains"|"propertyNames"|"if"|"then"|"else"|"not"|"unevaluatedItems"|"unevaluatedProperties"|"contentSchema"=>{
                if matches!(v, Value::Object(_) | Value::Bool(_)){ let mut p=ptr.clone(); p.push(k.clone()); out.push(p); }
            }
            _=>{}
        }
    }
}

// ---------- Output units ----------
#[derive(Clone,Debug)]
pub struct Unit {
    pub eval_path: String,
    pub inst_path: String,
    pub schema_loc: String,
    pub valid: bool,
    pub annotations: Option<Value>,
    pub dropped: Option<Value>,
    pub errors: Option<BTreeMap<String, ErrorVal>>,
    pub details: Vec<Unit>,
}
#[derive(Clone,Debug)]
pub enum ErrorVal{ Single(String), Multi(Vec<String>) }
impl ErrorVal{
    pub fn to_value(&self)->Value{
        match self{ ErrorVal::Single(s)=>Value::String(s.clone()), ErrorVal::Multi(v)=>Value::Array(v.iter().map(|s|Value::String(s.clone())).collect()) }
    }
}
impl Unit {
    pub fn new(eval_path:String, inst_path:String, schema_loc:String, valid:bool)->Self{ Self{eval_path,inst_path,schema_loc,valid,annotations:None,dropped:None,errors:None,details:vec![]} }
    pub fn to_json(&self, hierarchical:bool)->Value{
        let mut m=Map::new();
        if let Some(a)=&self.annotations{ m.insert("annotations".into(), a.clone()); }
        if let Some(d)=&self.dropped{ m.insert("droppedAnnotations".into(), d.clone()); }
        if let Some(e)=&self.errors{
            let mut em=Map::new(); for (k,v) in e{ em.insert(k.clone(), v.to_value()); } m.insert("errors".into(), Value::Object(em));
        }
        if hierarchical && !self.details.is_empty(){
            let details:Vec<Value>=self.details.iter().map(|u|u.to_json(true)).collect();
            m.insert("details".into(), Value::Array(details));
        }
        m.insert("evaluationPath".into(), Value::String(self.eval_path.clone()));
        m.insert("instanceLocation".into(), Value::String(self.inst_path.clone()));
        m.insert("schemaLocation".into(), Value::String(self.schema_loc.clone()));
        m.insert("valid".into(), Value::Bool(self.valid));
        Value::Object(m)
    }
    pub fn flatten(&self, out:&mut Vec<Value>){
        // pre-order, produce unit json without details
        let mut flat=self.clone(); flat.details.clear();
        out.push(flat.to_json(false));
        for d in &self.details{ d.flatten(out); }
    }
}

#[derive(Clone,Debug)]
pub struct Outcome {
    pub valid: bool,
    pub unit: Unit,
    pub errors: Vec<String>, // text errors in order
    pub evaluated_props: BTreeSet<String>,
    pub evaluated_items: BTreeSet<usize>,
    // internal for parents
    pub annotations_value: Option<Value>, // annotation produced by this schema application (for refs etc?) not used
}

fn fmt_val(v:&Value)->String{ num::format_json(v) }
fn fmt_instance(v:&Value)->String{ fmt_val(v) }

// ---------- Validator ----------
pub struct Validator {
    pub registry: Registry,
    pub root: CNode,
    pub assert_format: bool,
}
pub struct BuildError {
    pub message: String,
    pub is_meta: bool,
    pub meta_validator: Option<Box<Validator>>, // for non-text meta output
    pub meta_first_error: Option<String>,
}
impl BuildError {
    pub fn msg(s:String)->Self{ Self{message:s.clone(), is_meta:false, meta_validator:None, meta_first_error:Some(s)} }
}

fn get_obj<'a>(v:&'a Value)->Option<&'a Map<String,Value>>{ if let Value::Object(m)=v{Some(m)}else{None} }

// helpers for error messages
fn err_type_single(inst:&Value, t:&str)->String{ format!("{} is not of type \"{}\"", fmt_instance(inst), t) }

pub fn quoted_list_names(names:&[String])->String{
    // ('a', 'b') formatting returns contents without parentheses
    names.iter().map(|n|format!("'{}'", n)).collect::<Vec<_>>().join(", ")
}
pub fn was_were(n:usize)->&'static str{ if n==1{"was"}else{"were"} }

impl Validator {
    pub fn is_valid(&self, instance:&Value)->bool{
        let mut scope=Vec::new(); let mut stack=Vec::new();
        self.eval_node(&self.root, instance, String::new(), String::new(), &mut scope, &mut stack).valid
    }
    pub fn apply(&self, instance:&Value)->Outcome{
        let mut scope=Vec::new(); let mut stack=Vec::new();
        self.eval_node(&self.root, instance, String::new(), String::new(), &mut scope, &mut stack)
    }

    fn child_node(&self, parent:&CNode, adjusted:&Adjusted, tokens:&[&str])->CNode{
        let mut ptr=parent.ptr.clone(); for t in tokens{ ptr.push(t.to_string()); }
        CNode{doc:parent.doc, ptr, base_uri:adjusted.base_uri.clone(), loc_uri:adjusted.loc_uri.clone(), loc_root:adjusted.loc_root.clone(), draft:adjusted.draft}
    }

    fn eval_node(&self, node_in:&CNode, instance:&Value, inst_path:String, eval_path:String, dyn_scope:&mut Vec<DynamicFrame>, stack:&mut Vec<(NodeKey,String,usize)>)->Outcome{
        // adjust for own $id / draft
        let adj = self.adjust(node_in);
        let node = &adj.node;
        // stack depth counting
        let key=(node.key(), inst_path.clone());
        let count = stack.iter().filter(|(k,ip,_)| k==&node.key() && ip==&inst_path).count();
        stack.push((node.key(), inst_path.clone(), count));
        let result = self.eval_node_inner(node_in, &adj, instance, inst_path.clone(), eval_path, dyn_scope, stack);
        stack.pop();
        let _=key;
        result
    }

    fn adjust(&self, node:&CNode)->Adjusted{
        // compute effective loc/base/draft for node own $id/$schema
        let val=self.registry.get_node_value(node.doc,&node.ptr).cloned().unwrap_or(Value::Null);
        let mut base=node.base_uri.clone();
        let mut loc_uri=node.loc_uri.clone();
        let mut loc_root=node.loc_root.clone();
        let mut draft=node.draft;
        if let Value::Object(obj)=&val{
            if let Some(idv)=obj.get("$id").and_then(|v|v.as_str()){
                let resolved=uri::resolve_uri(&base,idv);
                base=uri::without_fragment(&resolved);
                loc_uri=base.clone(); loc_root=node.ptr.clone();
            } else if draft==Draft::D4 {
                if let Some(idv)=obj.get("id").and_then(|v|v.as_str()){
                    let resolved=uri::resolve_uri(&base,idv);
                    base=uri::without_fragment(&resolved);
                    loc_uri=base.clone(); loc_root=node.ptr.clone();
                }
            }
            if let Some(s)=obj.get("$schema").and_then(|v|v.as_str()){
                if let Some(d)=detect_known_draft(s){
                    // only apply if this node is a resource root (root ptr or has id) - approximation: apply when ptr empty or node has $id
                    if node.ptr.is_empty() || obj.contains_key("$id"){ draft=d; }
                }
            }
        }
        Adjusted{ node:CNode{doc:node.doc,ptr:node.ptr.clone(),base_uri:node.base_uri.clone(),loc_uri:loc_uri.clone(),loc_root:loc_root.clone(),draft}, value:val, base_uri:base, loc_uri, loc_root, draft }
    }

    fn schema_loc(&self, adj:&Adjusted)->String{
        // loc_root relative pointer
        let rel = if adj.node.ptr.len()>=adj.loc_root.len() && adj.node.ptr[..adj.loc_root.len()]==adj.loc_root[..] { adj.node.ptr[adj.loc_root.len()..].to_vec() } else { adj.node.ptr.clone() };
        format!("{}#{}", adj.loc_uri, pointer_to_string(&rel))
    }
    fn keyword_loc(&self, adj:&Adjusted, keyword:&str)->String{
        format!("{}/{}", self.schema_loc(adj), uri::escape_pointer_token(keyword))
    }
    fn child_loc(&self, adj:&Adjusted, tokens:&[String])->String{
        let mut s=self.schema_loc(adj);
        for t in tokens{ s.push('/'); s.push_str(&uri::escape_pointer_token(t)); }
        s
    }

    fn eval_node_inner(&self, node_in:&CNode, adj:&Adjusted, instance:&Value, inst_path:String, eval_path:String, dyn_scope:&mut Vec<DynamicFrame>, stack:&mut Vec<(NodeKey,String,usize)>)->Outcome{
        let node=&adj.node;
        let val=&adj.value;
        // bool
        if let Value::Bool(b)=val{
            let mut unit=Unit::new(eval_path.clone(), inst_path.clone(), self.schema_loc(adj), *b);
            if !b {
                let mut errs=BTreeMap::new(); errs.insert("falseSchema".to_string(), ErrorVal::Single(format!("False schema does not allow {}", fmt_instance(instance))));
                unit.errors=Some(errs);
                return Outcome{valid:false, unit, errors:vec![format!("False schema does not allow {}", fmt_instance(instance))], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new(), annotations_value:None};
            } else {
                return Outcome{valid:true, unit, errors:vec![], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new(), annotations_value:None};
            }
        }
        let obj = match val { Value::Object(m)=>m, _=>{
            // For a non-object non-bool user schema (won't pass meta usually) treat as valid?
            let unit=Unit::new(eval_path.clone(), inst_path.clone(), self.schema_loc(adj), true);
            return Outcome{valid:true, unit, errors:vec![], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new(), annotations_value:None};
        }};
        let draft=adj.draft;

        // pre-2019 $ref exclusive
        let has_ref = obj.contains_key("$ref");
        let has_dyn_ref = obj.contains_key("$dynamicRef");
        let has_rec_ref = obj.contains_key("$recursiveRef");
        if draft!=Draft::D2019 && draft!=Draft::D2020 && has_ref {
            // evaluate only $ref
            let ann = self.node_annotations(obj,draft);
            let mut root_unit=Unit::new(eval_path.clone(), inst_path.clone(), self.schema_loc(adj), true);
            let mut outcome_errors=Vec::new(); let mut eval_props=BTreeSet::new(); let mut eval_items=BTreeSet::new();
            // $ref evaluation appends unit
            let ref_out = self.eval_ref_keyword(node, adj, obj.get("$ref").unwrap(), instance, &inst_path, &eval_path, dyn_scope, stack, false);
            let valid=ref_out.valid;
            if let Some(u)=ref_out.unit_opt{ root_unit.details.push(u); }
            outcome_errors.extend(ref_out.errors);
            eval_props.extend(ref_out.evaluated_props); eval_items.extend(ref_out.evaluated_items);
            root_unit.valid=valid;
            // annotations
            if let Some(a)=ann { if valid{ root_unit.annotations=Some(a);} else { root_unit.dropped=Some(a);} }
            return Outcome{valid, unit:root_unit, errors:outcome_errors, evaluated_props:eval_props, evaluated_items:eval_items, annotations_value:None};
        }
        if draft==Draft::D2019 && has_rec_ref {
            // recursiveRef similar exclusive? In 2019, $recursiveRef replaces but siblings? treat as ref and continue others? Spec 2019 $recursiveRef similar to dynamic; we'll evaluate as ref keyword at end below by mapping.
        }

        // Collect outcomes for keywords, assemble in priority.
        // We'll evaluate in logical phases and store unit nodes in a map keyed by order.
        let mut ordered_units: Vec<(i32, Unit)> = Vec::new();
        let mut errors: Vec<String> = Vec::new();
        let mut valid=true;
        let mut evaluated_props: BTreeSet<String> = BTreeSet::new();
        let mut evaluated_items: BTreeSet<usize> = BTreeSet::new();

        // helper closure not possible easily; we'll inline.

        // === Type / const / enum ===
        // priority mapping function
        // TYPE
        if let Some(tv)=obj.get("type"){
            let (u, v, errs)=self.eval_type(tv, instance, &eval_path, &self.keyword_loc(adj,"type"), &inst_path);
            valid &= v; errors.extend(errs); ordered_units.push((10,u));
        }
        if draft!=Draft::D4 {
            if let Some(cv)=obj.get("const"){
                let v=num::json_eq(instance,cv);
                let mut u=Unit::new(format!("{}/const",eval_path), inst_path.clone(), self.keyword_loc(adj,"const"), v);
                let mut errs=vec![];
                if !v{ let msg=format!("{} was expected", fmt_instance(cv)); let mut em=BTreeMap::new(); em.insert("const".into(),ErrorVal::Single(msg.clone())); u.errors=Some(em); errs.push(msg); }
                valid&=v; errors.extend(errs); ordered_units.push((20,u));
            }
        }
        if let Some(ev)=obj.get("enum"){
            if let Value::Array(cands)=ev{
                let v=cands.iter().any(|c|num::json_eq(instance,c));
                let mut u=Unit::new(format!("{}/enum",eval_path), inst_path.clone(), self.keyword_loc(adj,"enum"), v);
                let mut errs=vec![];
                if !v{ let msg=enum_message(instance,cands); let mut em=BTreeMap::new(); em.insert("enum".into(),ErrorVal::Single(msg.clone())); u.errors=Some(em); errs.push(msg); }
                valid&=v; errors.extend(errs); ordered_units.push((30,u));
            }
        }

        // === Numeric / string / array / object scalar constraints ===
        // numeric
        let is_num = matches!(instance, Value::Number(_));
        let inst_dec = num::decimal_of(instance);
        // D4 exclusive handling combined with minimum/maximum
        if draft==Draft::D4 {
            if let Some(minv)=obj.get("minimum"){
                let excl = obj.get("exclusiveMinimum").and_then(|v|v.as_bool()).unwrap_or(false);
                let mut v=true; let mut msg:Option<String>=None; let mut ekey="minimum";
                if is_num {
                    if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(minv)){
                        if excl { if num::cmp_decimal(&a,&b)!=std::cmp::Ordering::Greater { v=false; msg=Some(format!("{} is less than or equal to the minimum of {}", fmt_instance(instance), fmt_instance(minv))); ekey="exclusiveMinimum"; } }
                        else if num::cmp_decimal(&a,&b)==std::cmp::Ordering::Less { v=false; msg=Some(format!("{} is less than the minimum of {}", fmt_instance(instance), fmt_instance(minv))); }
                    }
                }
                let mut u=Unit::new(format!("{}/minimum",eval_path), inst_path.clone(), self.keyword_loc(adj,"minimum"), v);
                let mut errs=vec![];
                if let Some(m)=msg { let mut em=BTreeMap::new(); em.insert(ekey.into(),ErrorVal::Single(m.clone())); u.errors=Some(em); errs.push(m); }
                valid&=v; errors.extend(errs); ordered_units.push((40,u));
            }
            if let Some(maxv)=obj.get("maximum"){
                let excl = obj.get("exclusiveMaximum").and_then(|v|v.as_bool()).unwrap_or(false);
                let mut v=true; let mut msg:Option<String>=None; let mut ekey="maximum";
                if is_num {
                    if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(maxv)){
                        if excl { if num::cmp_decimal(&a,&b)!=std::cmp::Ordering::Less { v=false; msg=Some(format!("{} is greater than or equal to the maximum of {}", fmt_instance(instance), fmt_instance(maxv))); ekey="exclusiveMaximum"; } }
                        else if num::cmp_decimal(&a,&b)==std::cmp::Ordering::Greater { v=false; msg=Some(format!("{} is greater than the maximum of {}", fmt_instance(instance), fmt_instance(maxv))); }
                    }
                }
                let mut u=Unit::new(format!("{}/maximum",eval_path), inst_path.clone(), self.keyword_loc(adj,"maximum"), v);
                let mut errs=vec![];
                if let Some(m)=msg { let mut em=BTreeMap::new(); em.insert(ekey.into(),ErrorVal::Single(m.clone())); u.errors=Some(em); errs.push(m); }
                valid&=v; errors.extend(errs); ordered_units.push((41,u));
            }
        } else {
            if let Some(minv)=obj.get("minimum"){
                let mut v=true; let mut msg=None;
                if is_num { if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(minv)){ if num::cmp_decimal(&a,&b)==std::cmp::Ordering::Less {v=false; msg=Some(format!("{} is less than the minimum of {}", fmt_instance(instance), fmt_instance(minv)));}}}
                let (u,errs)=make_leaf(format!("{}/minimum",eval_path), inst_path.clone(), self.keyword_loc(adj,"minimum"), v, "minimum", msg);
                valid&=v; errors.extend(errs); ordered_units.push((40,u));
            }
            if let Some(maxv)=obj.get("maximum"){
                let mut v=true; let mut msg=None;
                if is_num { if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(maxv)){ if num::cmp_decimal(&a,&b)==std::cmp::Ordering::Greater {v=false; msg=Some(format!("{} is greater than the maximum of {}", fmt_instance(instance), fmt_instance(maxv)));}}}
                let (u,errs)=make_leaf(format!("{}/maximum",eval_path), inst_path.clone(), self.keyword_loc(adj,"maximum"), v, "maximum", msg);
                valid&=v; errors.extend(errs); ordered_units.push((41,u));
            }
            if let Some(exv)=obj.get("exclusiveMinimum"){
                let mut v=true; let mut msg=None;
                if is_num { if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(exv)){ if num::cmp_decimal(&a,&b)!=std::cmp::Ordering::Greater {v=false; msg=Some(format!("{} is less than or equal to the minimum of {}", fmt_instance(instance), fmt_instance(exv)));}}}
                let (u,errs)=make_leaf(format!("{}/exclusiveMinimum",eval_path), inst_path.clone(), self.keyword_loc(adj,"exclusiveMinimum"), v, "exclusiveMinimum", msg);
                valid&=v; errors.extend(errs); ordered_units.push((42,u));
            }
            if let Some(exv)=obj.get("exclusiveMaximum"){
                let mut v=true; let mut msg=None;
                if is_num { if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(exv)){ if num::cmp_decimal(&a,&b)!=std::cmp::Ordering::Less {v=false; msg=Some(format!("{} is greater than or equal to the maximum of {}", fmt_instance(instance), fmt_instance(exv)));}}}
                let (u,errs)=make_leaf(format!("{}/exclusiveMaximum",eval_path), inst_path.clone(), self.keyword_loc(adj,"exclusiveMaximum"), v, "exclusiveMaximum", msg);
                valid&=v; errors.extend(errs); ordered_units.push((43,u));
            }
        }
        if let Some(mv)=obj.get("multipleOf"){
            let mut v=true; let mut msg=None;
            if is_num { if let (Some(a),Some(b))=(inst_dec.clone(), num::decimal_of(mv)){ if !b.is_zero() && !num::is_multiple_of(&a,&b){ v=false; msg=Some(format!("{} is not a multiple of {}", fmt_instance(instance), fmt_instance(mv))); } } }
            let (u,errs)=make_leaf(format!("{}/multipleOf",eval_path), inst_path.clone(), self.keyword_loc(adj,"multipleOf"), v, "multipleOf", msg);
            valid&=v; errors.extend(errs); ordered_units.push((44,u));
        }
        // strings
        let inst_str: Option<&str> = instance.as_str();
        if let Some(nv)=obj.get("minLength"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Some(s)=inst_str{ let cnt=s.chars().count(); if cnt<n {v=false; msg=Some(format!("{} is shorter than {} character{}", fmt_instance(instance), n, if n==1{""}else{"s"}));}}
                let (u,errs)=make_leaf(format!("{}/minLength",eval_path), inst_path.clone(), self.keyword_loc(adj,"minLength"), v, "minLength", msg);
                valid&=v; errors.extend(errs); ordered_units.push((50,u));
            }
        }
        if let Some(nv)=obj.get("maxLength"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Some(s)=inst_str{ let cnt=s.chars().count(); if cnt>n {v=false; msg=Some(format!("{} is longer than {} character{}", fmt_instance(instance), n, if n==1{""}else{"s"}));}}
                let (u,errs)=make_leaf(format!("{}/maxLength",eval_path), inst_path.clone(), self.keyword_loc(adj,"maxLength"), v, "maxLength", msg);
                valid&=v; errors.extend(errs); ordered_units.push((51,u));
            }
        }
        // arrays size
        if let Some(nv)=obj.get("minItems"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Value::Array(a)=instance{ if a.len()<n {v=false; msg=Some(format!("{} has less than {} item{}", fmt_instance(instance), n, if n==1{""}else{"s"}));}}
                let (u,errs)=make_leaf(format!("{}/minItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"minItems"), v, "minItems", msg);
                valid&=v; errors.extend(errs); ordered_units.push((52,u));
            }
        }
        if let Some(nv)=obj.get("maxItems"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Value::Array(a)=instance{ if a.len()>n {v=false; msg=Some(format!("{} has more than {} item{}", fmt_instance(instance), n, if n==1{""}else{"s"}));}}
                let (u,errs)=make_leaf(format!("{}/maxItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"maxItems"), v, "maxItems", msg);
                valid&=v; errors.extend(errs); ordered_units.push((53,u));
            }
        }
        if let Some(nv)=obj.get("minProperties"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Value::Object(m)=instance{ if m.len()<n {v=false; msg=Some(format!("{} has less than {} propert{}", fmt_instance(instance), n, if n==1{"y"}else{"ies"}));}}
                let (u,errs)=make_leaf(format!("{}/minProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"minProperties"), v, "minProperties", msg);
                valid&=v; errors.extend(errs); ordered_units.push((54,u));
            }
        }
        if let Some(nv)=obj.get("maxProperties"){
            if let Some(n)=as_usize(nv){
                let mut v=true; let mut msg=None;
                if let Value::Object(m)=instance{ if m.len()>n {v=false; msg=Some(format!("{} has more than {} propert{}", fmt_instance(instance), n, if n==1{"y"}else{"ies"}));}}
                let (u,errs)=make_leaf(format!("{}/maxProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"maxProperties"), v, "maxProperties", msg);
                valid&=v; errors.extend(errs); ordered_units.push((55,u));
            }
        }
        if let Some(uv)=obj.get("uniqueItems"){
            if draft!=Draft::D4 { /* uniqueItems was in draft4 too */ }
            if uv.as_bool().unwrap_or(false){
                let mut v=true; let mut msg=None;
                if let Value::Array(a)=instance{
                    'outer: for i in 0..a.len(){ for j in i+1..a.len(){ if num::json_eq(&a[i],&a[j]){ v=false; break 'outer; } } }
                    if !v { msg=Some(format!("{} has non-unique elements", fmt_instance(instance))); }
                }
                let (u,errs)=make_leaf(format!("{}/uniqueItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"uniqueItems"), v, "uniqueItems", msg);
                valid&=v; errors.extend(errs); ordered_units.push((56,u));
            } else if uv.as_bool()==Some(false){
                // no node? Observed schema with uniqueItems false gave no single node when other nodes missing? It had no unique unit... We'll still add? Test earlier: schema {"uniqueItems":false} within schema2 missing - order list didn't show. So skip false
            }
        }

        // required
        let mut required_missing: Vec<String>=Vec::new();
        if let Some(rv)=obj.get("required"){
            if let Value::Array(arr)=rv{
                if let Value::Object(m)=instance{
                    for item in arr{ if let Some(name)=item.as_str(){ if !m.contains_key(name){ required_missing.push(name.to_string()); } } }
                    let v=required_missing.is_empty();
                    let mut u=Unit::new(format!("{}/required",eval_path), inst_path.clone(), self.keyword_loc(adj,"required"), v);
                    let mut errs=vec![];
                    if !v {
                        let msgs:Vec<String>=required_missing.iter().map(|n|format!("\"{}\" is a required property", n)).collect();
                        let mut em=BTreeMap::new();
                        if msgs.len()==1{ em.insert("required".into(), ErrorVal::Single(msgs[0].clone())); } else { em.insert("required".into(), ErrorVal::Multi(msgs.clone())); }
                        u.errors=Some(em); errs.extend(msgs);
                    }
                    valid&=v; errors.extend(errs); ordered_units.push((60,u));
                } else {
                    // unit present valid true
                    let u=Unit::new(format!("{}/required",eval_path), inst_path.clone(), self.keyword_loc(adj,"required"), true);
                    ordered_units.push((60,u));
                }
            }
        }
        // dependentRequired & dependencies (array form)
        // We'll compute later as part of dependent phase but required rank 61 for dependentRequired
        let mut dependent_units: Vec<Unit>=Vec::new();
        let mut dependent_valid=true; let mut dependent_errors:Vec<String>=Vec::new();
        if draft==Draft::D2019 || draft==Draft::D2020 {
            if let Some(Value::Object(deps))=obj.get("dependentRequired"){
                let (u,v,errs)=self.eval_dependent_required(node, adj, deps, instance, &inst_path, &eval_path, "dependentRequired", 61, dyn_scope, stack);
                dependent_valid&=v; dependent_errors.extend(errs); if let Some(u)=u{dependent_units.push(u);}
            }
        }
        // dependencies in all drafts (also 2019+ as legacy)
        if let Some(Value::Object(deps))=obj.get("dependencies"){
            // split: array forms as dependentRequired-like, schema forms as dependentSchemas-like; ranking: dependencies probably near dependentRequired/dependentSchemas... We'll treat array at 61 and schema at later
            // First array
            let mut arr_deps=Map::new();
            for (k,v) in deps { if v.is_array(){ arr_deps.insert(k.clone(),v.clone()); } }
            if !arr_deps.is_empty(){
                let (u,v,errs)=self.eval_dependent_required(node, adj, &arr_deps, instance, &inst_path, &eval_path, "dependencies", 61, dyn_scope, stack);
                dependent_valid&=v; dependent_errors.extend(errs); if let Some(u)=u{dependent_units.push(u);}
            }
        }
        if !dependent_units.is_empty() || obj.contains_key("dependentRequired") || obj.contains_key("dependencies") {
            // push units
            for u in dependent_units { ordered_units.push((61,u)); }
            valid&=dependent_valid; errors.extend(dependent_errors);
        }

        // pattern
        if let Some(pv)=obj.get("pattern"){
            if let Some(pat)=pv.as_str(){
                let mut v=true; let mut msg=None;
                if let Some(s)=inst_str{
                    match fancy_regex::Regex::new(pat){ Ok(re)=>{ if !re.is_match(s).unwrap_or(false){ v=false; msg=Some(format!("{} does not match \"{}\"", fmt_instance(instance), pat)); } } Err(_)=>{ v=false; msg=Some(format!("{} is not a \"regex\"", fmt_instance(pv))); } }
                }
                let (u,errs)=make_leaf(format!("{}/pattern",eval_path), inst_path.clone(), self.keyword_loc(adj,"pattern"), v, "pattern", msg);
                valid&=v; errors.extend(errs); ordered_units.push((70,u));
            }
        }
        // format
        if let Some(fv)=obj.get("format"){
            if let Some(fname)=fv.as_str(){
                if self.assert_format && formats::formats_enabled(&draft,fname){
                    let mut v=true; let mut msg=None;
                    if let Some(s)=inst_str{ if !formats::validate_format(fname,s){ v=false; msg=Some(format!("{} is not a \"{}\"", fmt_instance(instance), fname)); } }
                    let (u,errs)=make_leaf(format!("{}/format",eval_path), inst_path.clone(), self.keyword_loc(adj,"format"), v, "format", msg);
                    valid&=v; errors.extend(errs); ordered_units.push((71,u));
                }
            }
        }

        // --- Applicators for object/array that need internal evaluation ---
        // Compute outcomes once for properties etc to reuse for additional/unevaluated
        let obj_instance: Option<&Map<String,Value>> = match instance{ Value::Object(m)=>Some(m), _=>None };
        let arr_instance: Option<&Vec<Value>> = match instance{ Value::Array(a)=>Some(a), _=>None };

        // Prepare results holders
        let mut prop_keyword_unit: Option<Unit>=None;
        let mut prop_child_units: Vec<Unit>=Vec::new();
        let mut prop_valid=true; let mut prop_errors:Vec<String>=Vec::new();
        let mut prop_evaluated: BTreeSet<String>=BTreeSet::new();

        let mut pattern_keyword_unit: Option<Unit>=None;
        let mut pattern_child_units: Vec<Unit>=Vec::new();
        let mut pattern_valid=true; let mut pattern_errors:Vec<String>=Vec::new();
        let mut pattern_evaluated: BTreeSet<String>=BTreeSet::new();

        // properties
        if let Some(Value::Object(props))=obj.get("properties"){
            if let Some(inst_obj)=obj_instance{
                let mut matched: Vec<String>=Vec::new();
                for (name, val) in inst_obj.iter(){
                    if let Some(subschema)=props.get(name){
                        matched.push(name.clone());
                        prop_evaluated.insert(name.clone());
                        let child_node=self.child_node(node, adj, &["properties", name]);
                        let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path, uri::escape_pointer_token(name)), format!("{}/properties/{}",eval_path, uri::escape_pointer_token(name)), dyn_scope, stack);
                        prop_valid&=out.valid;
                        prop_errors.extend(out.errors.clone());
                        prop_child_units.push(out.unit);
                        let _=subschema;
                    }
                }
                let ann = Value::Array(matched.iter().map(|n|Value::String(n.clone())).collect());
                let mut ku=Unit::new(format!("{}/properties",eval_path), inst_path.clone(), self.keyword_loc(adj,"properties"), prop_valid);
                if prop_valid{ ku.annotations=Some(ann);} else { ku.dropped=Some(ann); }
                prop_keyword_unit=Some(ku);
            } else {
                // non-object: keyword unit valid true with annotation []? Original for non-object properties keyword: annotations [] ? For meta properties..., but user validation on number: properties unit annotation [] likely.
                let mut ku=Unit::new(format!("{}/properties",eval_path), inst_path.clone(), self.keyword_loc(adj,"properties"), true);
                ku.annotations=Some(Value::Array(vec![]));
                prop_keyword_unit=Some(ku);
            }
        }
        // patternProperties
        let mut pattern_regexes: Vec<(String, fancy_regex::Regex)> = Vec::new();
        if let Some(Value::Object(pats))=obj.get("patternProperties"){
            // compile in sorted key order (BTree iteration)
            for (pat,_) in pats { if let Ok(re)=fancy_regex::Regex::new(pat){ pattern_regexes.push((pat.clone(), re)); } }
            if let Some(inst_obj)=obj_instance{
                let mut matched_names: Vec<String>=Vec::new();
                for (name,val) in inst_obj.iter(){
                    for (pat,re) in &pattern_regexes{
                        if re.is_match(name).unwrap_or(false){
                            if !matched_names.contains(name){ matched_names.push(name.clone()); }
                            pattern_evaluated.insert(name.clone());
                            let child_node=self.child_node(node, adj, &["patternProperties", pat]);
                            let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path, uri::escape_pointer_token(name)), format!("{}/patternProperties/{}",eval_path, uri::escape_pointer_token(pat)), dyn_scope, stack);
                            pattern_valid&=out.valid;
                            pattern_errors.extend(out.errors.clone());
                            pattern_child_units.push(out.unit);
                        }
                    }
                }
                matched_names.sort();
                let ann=Value::Array(matched_names.iter().map(|n|Value::String(n.clone())).collect());
                let mut ku=Unit::new(format!("{}/patternProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"patternProperties"), pattern_valid);
                if pattern_valid{ ku.annotations=Some(ann);} else { ku.dropped=Some(ann); }
                pattern_keyword_unit=Some(ku);
            } else {
                let mut ku=Unit::new(format!("{}/patternProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"patternProperties"), true);
                ku.annotations=Some(Value::Array(vec![]));
                pattern_keyword_unit=Some(ku);
            }
        }

        // additionalProperties
        let has_additional = obj.contains_key("additionalProperties");
        let has_props_or_patterns = obj.contains_key("properties")||obj.contains_key("patternProperties");
        // propertyNames outcome (computed before additional? order in list is after but logic independent)
        let mut propnames_unit: Option<Unit>=None; let mut propnames_valid=true; let mut propnames_errors:Vec<String>=Vec::new();
        if let Some(sub)=obj.get("propertyNames"){
            if draft!=Draft::D4 {
                if let Some(inst_obj)=obj_instance{
                    // keyword unit initial
                    let mut ku=Unit::new(format!("{}/propertyNames",eval_path), inst_path.clone(), self.keyword_loc(adj,"propertyNames"), true);
                    // evaluating per name
                    let mut child_units=Vec::new();
                    // special false handling: if subschema is false, keyword unit directly gets falseSchema error with whole instance (observed)
                    if let Value::Bool(false)=sub {
                        let mut em=BTreeMap::new(); em.insert("falseSchema".into(), ErrorVal::Single(format!("False schema does not allow {}", fmt_instance(instance))));
                        ku.errors=Some(em); ku.valid=false; propnames_valid=false; propnames_errors.push(format!("False schema does not allow {}", fmt_instance(instance)));
                    } else {
                        for (name,_) in inst_obj.iter(){
                            let name_val=Value::String(name.clone());
                            let child_node=self.child_node(node,adj,&["propertyNames"]);
                            // eval_path for subschema unit is /propertyNames (same), its children append within node eval (eval_node will use eval_path passed)
                            let out=self.eval_node(&child_node, &name_val, inst_path.clone(), format!("{}/propertyNames",eval_path), dyn_scope, stack);
                            propnames_valid&=out.valid;
                            propnames_errors.extend(out.errors.clone());
                            child_units.push(out.unit);
                        }
                        ku.valid=propnames_valid;
                        ku.details=child_units;
                    }
                    propnames_unit=Some(ku);
                } else {
                    let ku=Unit::new(format!("{}/propertyNames",eval_path), inst_path.clone(), self.keyword_loc(adj,"propertyNames"), true);
                    propnames_unit=Some(ku);
                }
            }
        }

        // Additional evaluation
        let mut additional_unit: Option<Unit>=None; let mut additional_valid=true; let mut additional_errors:Vec<String>=Vec::new();
        let mut additional_evaluated: BTreeSet<String>=BTreeSet::new();
        if has_additional {
            let add_schema = obj.get("additionalProperties").unwrap();
            // If it's Bool true, node is omitted (optimization) unless ... observed standalone true omitted completely
            let is_true = matches!(add_schema, Value::Bool(true));
            if !is_true {
                if let Some(inst_obj)=obj_instance{
                    // compute remaining props
                    let mut remaining: Vec<String>=Vec::new();
                    for name in inst_obj.keys(){
                        if !prop_evaluated.contains(name) && !pattern_evaluated.contains(name){ remaining.push(name.clone()); }
                    }
                    if has_props_or_patterns {
                        // composite node: additional unit is parent, details are prop/pattern child units (handled in assembly)
                        let mut ku=Unit::new(format!("{}/additionalProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalProperties"), true);
                        if let Value::Bool(false)=add_schema{
                            if !remaining.is_empty(){
                                additional_valid=false;
                                let msg=format!("Additional properties are not allowed ({}{})", quoted_list_names(&remaining), format!(" {} unexpected", "")); // will fix below
                                // Build proper message:
                                let msg=additional_properties_message(&remaining);
                                let mut em=BTreeMap::new(); em.insert("additionalProperties".into(), ErrorVal::Single(msg.clone()));
                                ku.errors=Some(em); additional_errors.push(msg);
                            }
                            ku.valid=additional_valid;
                        } else {
                            // schema for remaining
                            let mut child_out_units=Vec::new();
                            let mut evaluated_names:Vec<String>=Vec::new();
                            for name in &remaining{
                                let val=&inst_obj[name];
                                evaluated_names.push(name.clone());
                                additional_evaluated.insert(name.clone());
                                let child_node=self.child_node(node,adj,&["additionalProperties"]);
                                let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path, uri::escape_pointer_token(name)), format!("{}/additionalProperties",eval_path), dyn_scope, stack);
                                additional_valid&=out.valid;
                                additional_errors.extend(out.errors.clone());
                                child_out_units.push(out.unit);
                            }
                            let ann=Value::Array(evaluated_names.iter().map(|n|Value::String(n.clone())).collect());
                            // In composite case original annotation? additional unit had droppedAnnotations ["b"] when failing in composite test. So set
                            if additional_valid{ ku.annotations=Some(ann);} else { ku.dropped=Some(ann); }
                            ku.valid=additional_valid;
                            ku.details=child_out_units; // will be merged with prop children in assembly (details order tricky); store temporarily in additional_unit.details and assembly will rearrange
                        }
                        additional_unit=Some(ku);
                    } else {
                        // standalone additional
                        // If False: observed single unit with falseSchema for first property? Only if remaining... Actually if any prop, unit errors falseSchema with value of first prop, valid false, no child units.
                        if let Value::Bool(false)=add_schema{
                            if !remaining.is_empty(){
                                additional_valid=false;
                                let first=&remaining[0];
                                let msg=format!("False schema does not allow {}", fmt_instance(&inst_obj[first]));
                                let mut ku=Unit::new(format!("{}/additionalProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalProperties"), false);
                                let mut em=BTreeMap::new(); em.insert("falseSchema".into(), ErrorVal::Single(msg.clone()));
                                ku.errors=Some(em); additional_errors.push(msg);
                                additional_unit=Some(ku);
                            } else {
                                let ku=Unit::new(format!("{}/additionalProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalProperties"), true);
                                additional_unit=Some(ku);
                            }
                        } else {
                            let mut child_units=Vec::new();
                            let mut evaluated_names:Vec<String>=Vec::new();
                            for name in &remaining{
                                let val=&inst_obj[name];
                                evaluated_names.push(name.clone());
                                additional_evaluated.insert(name.clone());
                                let child_node=self.child_node(node,adj,&["additionalProperties"]);
                                let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path, uri::escape_pointer_token(name)), format!("{}/additionalProperties",eval_path), dyn_scope, stack);
                                additional_valid&=out.valid;
                                additional_errors.extend(out.errors.clone());
                                child_units.push(out.unit);
                            }
                            let ann=Value::Array(evaluated_names.iter().map(|n|Value::String(n.clone())).collect());
                            let mut ku=Unit::new(format!("{}/additionalProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalProperties"), additional_valid);
                            if additional_valid{ ku.annotations=Some(ann);} else { ku.dropped=Some(ann); }
                            ku.details=child_units;
                            additional_unit=Some(ku);
                        }
                    }
                } else {
                    // non-object
                    let ku=Unit::new(format!("{}/additionalProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalProperties"), true);
                    additional_unit=Some(ku);
                }
            }
        }

        // items / prefixItems / contains
        // Need compute prefix outcome first internally but output order items before prefix
        let mut prefix_unit: Option<Unit>=None; let mut prefix_valid=true; let mut prefix_errors:Vec<String>=Vec::new(); let mut prefix_evaluated_items:BTreeSet<usize>=BTreeSet::new();
        let prefix_count: usize = if draft==Draft::D2020 || draft==Draft::D2019 {
            // prefixItems only 2020; in 2019 it's annotation/unknown so count 0 (items array handles)
            if draft==Draft::D2020 {
                if let Some(Value::Array(p))=obj.get("prefixItems"){ p.len() } else {0}
            } else {0}
        } else {0};
        if draft==Draft::D2020 {
            if let Some(Value::Array(pfx))=obj.get("prefixItems"){
                if let Some(inst_arr)=arr_instance{
                    let mut child_units=Vec::new();
                    for (i,_) in pfx.iter().enumerate(){
                        if i<inst_arr.len(){
                            prefix_evaluated_items.insert(i);
                            let child_node=self.child_node(node,adj,&["prefixItems",&i.to_string()]);
                            let out=self.eval_node(&child_node, &inst_arr[i], format!("{}/{}",inst_path,i), format!("{}/prefixItems/{}",eval_path,i), dyn_scope, stack);
                            prefix_valid&=out.valid; prefix_errors.extend(out.errors.clone()); child_units.push(out.unit);
                        }
                    }
                    // annotation: true if instance length <= prefix count? observed: if inst len 1 with 2 prefixes annotation true; if len 3 with 2 prefixes annotation 1 (last index)
                    let ann = if inst_arr.len()<=pfx.len(){ Value::Bool(true) } else { Value::Number(serde_json::Number::from((pfx.len()-1) as u64)) };
                    // if array empty? prefixItems [] not valid meta. If inst empty, annotation ??? maybe true
                    let mut ku=Unit::new(format!("{}/prefixItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"prefixItems"), prefix_valid);
                    if prefix_valid{ ku.annotations=Some(ann);} else { /* items annotation dropped? For prefix failing, original? We'll set dropped */ ku.dropped=Some(ann); if false {/*keep*/} ku.dropped=None; /* Actually earlier prefix+items failing prefixTrue gave annotations for true children; for failing children need check later */ if !prefix_valid { // set dropped only if annotation would?? We'll keep None for now
                        }
                    }
                    // Correction: observed prefixItems annotation when valid. When invalid, likely droppedAnnotations = ann. Let's set dropped
                    if !prefix_valid{ ku.dropped=Some(ann); }
                    ku.details=child_units;
                    prefix_unit=Some(ku);
                } else {
                    let ku=Unit::new(format!("{}/prefixItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"prefixItems"), true);
                    prefix_unit=Some(ku);
                }
            }
        }
        // items
        let mut items_unit: Option<Unit>=None; let mut items_valid=true; let mut items_errors:Vec<String>=Vec::new(); let mut items_evaluated: BTreeSet<usize>=BTreeSet::new();
        if let Some(items_schema)=obj.get("items"){
            match items_schema {
                Value::Array(arr_schemas)=>{
                    // pre-2020 only (2020 meta invalid)
                    if let Some(inst_arr)=arr_instance{
                        let mut child_units=Vec::new(); let mut any_child=false;
                        for (i,_) in arr_schemas.iter().enumerate(){
                            if i<inst_arr.len(){
                                any_child=true; items_evaluated.insert(i);
                                let child_node=self.child_node(node,adj,&["items",&i.to_string()]);
                                let out=self.eval_node(&child_node, &inst_arr[i], format!("{}/{}",inst_path,i), format!("{}/items/{}",eval_path,i), dyn_scope, stack);
                                items_valid&=out.valid; items_errors.extend(out.errors.clone()); child_units.push(out.unit);
                            }
                        }
                        if !matches!(items_schema, Value::Bool(true)){
                            let mut ku=Unit::new(format!("{}/items",eval_path), inst_path.clone(), self.keyword_loc(adj,"items"), items_valid);
                            ku.details=child_units; let _=any_child;
                            items_unit=Some(ku);
                        }
                    } else {
                        let ku=Unit::new(format!("{}/items",eval_path), inst_path.clone(), self.keyword_loc(adj,"items"), true);
                        items_unit=Some(ku);
                    }
                }
                Value::Object(_)|Value::Bool(_)=>{
                    // single schema
                    let is_true = matches!(items_schema, Value::Bool(true));
                    if !is_true {
                        if let Some(inst_arr)=arr_instance{
                            let start = if draft==Draft::D2020 { prefix_count } else {0};
                            let mut child_units=Vec::new();
                            for i in start..inst_arr.len(){
                                items_evaluated.insert(i);
                                let child_node=self.child_node(node,adj,&["items"]);
                                let out=self.eval_node(&child_node, &inst_arr[i], format!("{}/{}",inst_path,i), format!("{}/items",eval_path), dyn_scope, stack);
                                items_valid&=out.valid; items_errors.extend(out.errors.clone()); child_units.push(out.unit);
                            }
                            // annotation: true if any items evaluated beyond? observed: [1,2] no prefix => true; []=> false; non-array none (handled else)
                            let ann = Value::Bool(!inst_arr.is_empty() && start<inst_arr.len() || (draft!=Draft::D2020 && !inst_arr.is_empty()));
                            // For empty array annotation false
                            let ann = if inst_arr.is_empty(){ Value::Bool(false)} else { Value::Bool(true)};
                            let mut ku=Unit::new(format!("{}/items",eval_path), inst_path.clone(), self.keyword_loc(adj,"items"), items_valid);
                            if items_valid{ ku.annotations=Some(ann);} else { ku.dropped=Some(ann); }
                            ku.details=child_units;
                            items_unit=Some(ku);
                        } else {
                            let ku=Unit::new(format!("{}/items",eval_path), inst_path.clone(), self.keyword_loc(adj,"items"), true);
                            // no annotation for non-array
                            items_unit=Some(ku);
                        }
                    }
                }
                _=>{}
            }
        }
        // additionalItems (pre-2020, when items is array)
        let mut additional_items_unit: Option<Unit>=None; let mut additional_items_valid=true; let mut additional_items_errors:Vec<String>=Vec::new();
        if draft!=Draft::D2020 {
            if let Some(add)=obj.get("additionalItems"){
                if let Some(Value::Array(arr_schemas))=obj.get("items"){
                    if let Some(inst_arr)=arr_instance{
                        if inst_arr.len()>arr_schemas.len(){
                            let start=arr_schemas.len();
                            if let Value::Bool(false)=add{
                                additional_items_valid=false;
                                let extras:Vec<&Value>=inst_arr[start..].iter().collect();
                                let msg=additional_items_message(&extras);
                                let mut ku=Unit::new(format!("{}/additionalItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalItems"), false);
                                let mut em=BTreeMap::new(); em.insert("additionalItems".into(), ErrorVal::Single(msg.clone())); ku.errors=Some(em);
                                additional_items_errors.push(msg);
                                additional_items_unit=Some(ku);
                                // mark evaluated
                                for i in start..inst_arr.len(){ items_evaluated.insert(i); }
                            } else if let Value::Bool(true)=add{
                                // no unit
                            } else {
                                // schema: leaf unit consolidating errors? Original unit had errors {"type":...} for single extra. For multiple failing, errors value maybe list?
                                let mut child_errors:Vec<String>=Vec::new();
                                let mut first_error_key:Option<(String,String)>=None;
                                for i in start..inst_arr.len(){
                                    items_evaluated.insert(i);
                                    let child_node=self.child_node(node,adj,&["additionalItems"]);
                                    let out=self.eval_node(&child_node, &inst_arr[i], format!("{}/{}",inst_path,i), format!("{}/additionalItems",eval_path), dyn_scope, stack);
                                    // But original additionalItems unit is a leaf, not application node. We'll instead construct leaf from errors: discard out.unit, capture errors
                                    if !out.valid{
                                        additional_items_valid=false;
                                        // determine error key/message from out errors (first)
                                        // out.errors are messages; key guess from child schema? Use out.unit details to get errors map if leaf? Complex: Use generic: if child contains type etc, we re-derive by looking at out.unit.details errors
                                        // Simplify: collect out.errors and later set errors map with key "type" if message contains "is not of type" etc, else first key
                                        child_errors.extend(out.errors.clone());
                                        if first_error_key.is_none(){
                                            // extract first errors entry from flattened units
                                            let mut flat=Vec::new(); out.unit.flatten(&mut flat);
                                            for fv in flat { if let Value::Object(m)=fv { if let Some(Value::Object(em))=m.get("errors"){ for (k,v) in em{ if let Value::String(s)=v{ first_error_key=Some((k.clone(),s.clone())); break; } } } }
                                            }
                                        }
                                    }
                                }
                                additional_items_errors.extend(child_errors.clone());
                                let mut ku=Unit::new(format!("{}/additionalItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"additionalItems"), additional_items_valid);
                                if !additional_items_valid{
                                    let mut em=BTreeMap::new();
                                    if child_errors.len()==1{ em.insert(first_error_key.as_ref().map(|x|x.0.clone()).unwrap_or("type".into()), ErrorVal::Single(child_errors[0].clone())); }
                                    else if !child_errors.is_empty(){
                                        // group by key? Use first key with Multi
                                        let key=first_error_key.as_ref().map(|x|x.0.clone()).unwrap_or("type".into());
                                        em.insert(key, ErrorVal::Multi(child_errors.clone()));
                                    }
                                    ku.errors=Some(em);
                                }
                                additional_items_unit=Some(ku);
                            }
                        }
                    }
                }
            }
        }

        // contains
        let mut contains_unit: Option<Unit>=None; let mut contains_valid=true; let mut contains_errors:Vec<String>=Vec::new(); let mut contains_evaluated:BTreeSet<usize>=BTreeSet::new();
        if let Some(contains_schema)=obj.get("contains"){
            if draft!=Draft::D4 {
                if let Some(inst_arr)=arr_instance{
                    let mut matched_indices:Vec<usize>=Vec::new();
                    let mut matched_units:Vec<Unit>=Vec::new();
                    for (i,item) in inst_arr.iter().enumerate(){
                        let child_node=self.child_node(node,adj,&["contains"]);
                        let out=self.eval_node(&child_node, item, format!("{}/{}",inst_path,i), format!("{}/contains",eval_path), dyn_scope, stack);
                        if out.valid{ matched_indices.push(i); matched_units.push(out.unit); contains_evaluated.insert(i); }
                    }
                    let min_c = obj.get("minContains").and_then(as_usize).unwrap_or(1);
                    let max_c = obj.get("maxContains").and_then(as_usize);
                    let count=matched_indices.len();
                    let mut v=true;
                    if count<min_c{ v=false; }
                    if let Some(mx)=max_c{ if count>mx{ v=false; } }
                    contains_valid=v;
                    let mut ku=Unit::new(format!("{}/contains",eval_path), inst_path.clone(), self.keyword_loc(adj,"contains"), v);
                    if v{
                        ku.annotations=Some(Value::Array(matched_indices.iter().map(|i|Value::Number((*i as u64).into())).collect()));
                        ku.details=matched_units;
                    } else {
                        let msg=format!("None of {} are valid under the given schema", fmt_instance(instance));
                        let mut em=BTreeMap::new(); em.insert("contains".into(), ErrorVal::Single(msg.clone())); ku.errors=Some(em);
                        contains_errors.push(msg);
                        // matched units are dropped? Original failing contains with some matches but min not met: need check. For now if count>0 and failed due max/min, original list likely no details. Keep none.
                    }
                    contains_unit=Some(ku);
                } else {
                    let ku=Unit::new(format!("{}/contains",eval_path), inst_path.clone(), self.keyword_loc(adj,"contains"), true);
                    contains_unit=Some(ku);
                }
            }
        }

        // dependentSchemas + dependencies schema form
        let mut dep_schemas_units: Vec<Unit>=Vec::new(); let mut dep_schemas_valid=true; let mut dep_schemas_errors:Vec<String>=Vec::new();
        if draft==Draft::D2019 || draft==Draft::D2020 {
            if let Some(Value::Object(ds))=obj.get("dependentSchemas"){
                if let Some(inst_obj)=obj_instance{
                    let mut ku=Unit::new(format!("{}/dependentSchemas",eval_path), inst_path.clone(), self.keyword_loc(adj,"dependentSchemas"), true);
                    let mut children=Vec::new();
                    for (name,_) in ds.iter(){
                        if inst_obj.contains_key(name){
                            let child_node=self.child_node(node,adj,&["dependentSchemas",name]);
                            let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/dependentSchemas/{}",eval_path, uri::escape_pointer_token(name)), dyn_scope, stack);
                            dep_schemas_valid&=out.valid; dep_schemas_errors.extend(out.errors.clone()); children.push(out.unit);
                            if out.valid{ evaluated_props.extend(out.evaluated_props.clone()); }
                        }
                    }
                    ku.valid=dep_schemas_valid; ku.details=children; dep_schemas_units.push(ku);
                } else {
                    let ku=Unit::new(format!("{}/dependentSchemas",eval_path), inst_path.clone(), self.keyword_loc(adj,"dependentSchemas"), true);
                    dep_schemas_units.push(ku);
                }
            }
        }
        // dependencies schema forms (all drafts)
        {
            let mut dep_obj: Option<&Map<String,Value>>=None;
            if let Some(Value::Object(ds))=obj.get("dependencies"){ dep_obj=Some(ds); }
            if let Some(ds)=dep_obj{
                // check any schema forms
                let has_schema_form = ds.values().any(|v|matches!(v, Value::Object(_)|Value::Bool(_)));
                if has_schema_form{
                    if let Some(inst_obj)=obj_instance{
                        let mut ku=Unit::new(format!("{}/dependencies",eval_path), inst_path.clone(), self.keyword_loc(adj,"dependencies"), true);
                        let mut children=Vec::new();
                        for (name,sub) in ds.iter(){
                            if matches!(sub, Value::Object(_)|Value::Bool(_)) && inst_obj.contains_key(name){
                                let child_node=self.child_node(node,adj,&["dependencies",name]);
                                let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/dependencies/{}",eval_path, uri::escape_pointer_token(name)), dyn_scope, stack);
                                dep_schemas_valid&=out.valid; dep_schemas_errors.extend(out.errors.clone()); children.push(out.unit);
                                if out.valid{ evaluated_props.extend(out.evaluated_props.clone()); }
                            }
                        }
                        ku.valid=dep_schemas_valid; ku.details=children; dep_schemas_units.push(ku);
                    } else {
                        let ku=Unit::new(format!("{}/dependencies",eval_path), inst_path.clone(), self.keyword_loc(adj,"dependencies"), true);
                        dep_schemas_units.push(ku);
                    }
                }
            }
        }

        // Assemble object/array applicators into ordered units with their errors
        // properties / pattern / additional arrangement
        // Errors order for object keywords should follow list order: additional (80) before properties children etc but text errors earlier: patternProperties error before additional error in example (pattern child error, then additional). Our errors vector currently separate; we'll append in an ordering approximating text error generation (which is independent validate path). For text, errors order observed:
        // - additionalProperties special error appeared before properties children in some cases? Example pattern+additional: text ["x" type (properties b), pattern... wait that case had properties error first then pattern]. Another example properties a false + additional false: errors [false a, additional]. So additional error after prop children. In list output additional unit before children, but text errors follow validate iterator which may process properties first.
        // We'll append object errors in order: properties, patternProperties, additional, propertyNames
        // This matches examples.
        // First handle evaluated additions
        evaluated_props.extend(prop_evaluated.clone());
        evaluated_props.extend(pattern_evaluated.clone());
        evaluated_props.extend(additional_evaluated.clone());

        // Append units:
        // We'll push units into ordered_units with ranks: additional 80, properties 81 (keyword+children), pattern 82, propertyNames 83
        // However, if additional composite: prop keyword units are suppressed; additional unit details should include prop child units + pattern child units + (pattern keyword?) We'll follow observed simplified: additional unit first, then prop child units as root-level details (flatten will be slightly diff hierarchical but list order same as observed except pattern keyword position)
        if let Some(mut add_u)=additional_unit{
            if has_props_or_patterns{
                // attach prop/pattern children into add_u.details after its own child units (additional schema applications)
                let mut details: Vec<Unit>=Vec::new();
                // properties children first (observed for properties case add then /properties/a)
                // For pattern case, order in list: add, pattern child, pattern keyword
                details.extend(prop_child_units.clone());
                details.extend(pattern_child_units.clone());
                if let Some(pk)=pattern_keyword_unit.clone(){ details.push(pk); }
                // additional schema child units are already in add_u.details (for schema case) - they should come after? Observed composite additional schema case: list add, /properties/a, /additionalProperties (application), /additionalProperties/type, /pattern... So additional applications are interleaved by property order? Our simplified: add details = prop children, then original add details, then pattern children+keyword
                let orig = std::mem::take(&mut add_u.details);
                // reorder: prop, additional applications, pattern
                let mut merged=Vec::new();
                merged.extend(prop_child_units.clone());
                merged.extend(orig);
                merged.extend(pattern_child_units.clone());
                if let Some(pk)=pattern_keyword_unit.clone(){ merged.push(pk); }
                add_u.details=merged;
                let _=details;
                ordered_units.push((80,add_u));
                // do not push prop/pattern keyword units separately (properties suppressed, pattern already inside)
            } else {
                ordered_units.push((80,add_u));
                // standalone: prop/pattern not present
            }
        } else {
            // no additional (or true)
            if let Some(ku)=prop_keyword_unit.clone(){
                let mut ku=ku; ku.details=prop_child_units.clone(); ordered_units.push((81,ku));
            }
            if let Some(ku)=pattern_keyword_unit.clone(){
                let mut ku=ku; ku.details=pattern_child_units.clone(); ordered_units.push((82,ku));
            }
        }
        if has_additional && has_props_or_patterns {
            // if additional was true (add_unit None), then need prop units normally
            if ordered_units.iter().all(|(r,_)|*r!=80){
                if let Some(ku)=prop_keyword_unit.clone(){ let mut ku=ku; ku.details=prop_child_units.clone(); ordered_units.push((81,ku)); }
                if let Some(ku)=pattern_keyword_unit.clone(){ let mut ku=ku; ku.details=pattern_child_units.clone(); ordered_units.push((82,ku)); }
            }
        }
        if let Some(ku)=propnames_unit{ ordered_units.push((83,ku)); }
        // errors & valid for object applicators
        valid &= prop_valid; errors.extend(prop_errors.clone());
        valid &= pattern_valid; errors.extend(pattern_errors.clone());
        valid &= additional_valid; errors.extend(additional_errors.clone());
        valid &= propnames_valid; errors.extend(propnames_errors.clone());

        // items etc units ranks 90 items,91 prefix,92 additionalItems,93 contains
        if let Some(ku)=items_unit{ ordered_units.push((90,ku)); }
        if let Some(ku)=prefix_unit{ ordered_units.push((91,ku)); }
        if let Some(ku)=additional_items_unit{ ordered_units.push((92,ku)); }
        if let Some(ku)=contains_unit{ ordered_units.push((93,ku)); }
        valid &= items_valid; errors.extend(items_errors.clone());
        valid &= prefix_valid; errors.extend(prefix_errors.clone());
        valid &= additional_items_valid; errors.extend(additional_items_errors.clone());
        valid &= contains_valid; errors.extend(contains_errors.clone());
        evaluated_items.extend(prefix_evaluated_items.clone());
        evaluated_items.extend(items_evaluated.clone());
        evaluated_items.extend(contains_evaluated.clone());

        // dependentSchemas rank 100
        for u in dep_schemas_units{ ordered_units.push((100,u)); }
        valid &= dep_schemas_valid; errors.extend(dep_schemas_errors.clone());

        // allOf / anyOf / oneOf / not
        // allOf
        let mut allof_evaluated_props=BTreeSet::new(); let mut allof_evaluated_items=BTreeSet::new();
        if let Some(Value::Array(list))=obj.get("allOf"){
            let mut ku=Unit::new(format!("{}/allOf",eval_path), inst_path.clone(), self.keyword_loc(adj,"allOf"), true);
            let mut children=Vec::new(); let mut v=true; let mut errs=Vec::new();
            for (i,_) in list.iter().enumerate(){
                let child_node=self.child_node(node,adj,&["allOf",&i.to_string()]);
                let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/allOf/{}",eval_path,i), dyn_scope, stack);
                v&=out.valid; errs.extend(out.errors.clone()); children.push(out.unit);
                if out.valid{ allof_evaluated_props.extend(out.evaluated_props.clone()); allof_evaluated_items.extend(out.evaluated_items.clone()); }
            }
            ku.valid=v; ku.details=children;
            ordered_units.push((110,ku));
            valid&=v; errors.extend(errs);
            if v{ evaluated_props.extend(allof_evaluated_props); evaluated_items.extend(allof_evaluated_items); }
        }
        // anyOf
        if let Some(Value::Array(list))=obj.get("anyOf"){
            let mut ku=Unit::new(format!("{}/anyOf",eval_path), inst_path.clone(), self.keyword_loc(adj,"anyOf"), true);
            let mut children=Vec::new(); let mut any_valid=false; let mut branch_evaluated_props=BTreeSet::new(); let mut branch_evaluated_items=BTreeSet::new();
            let mut all_branch_errors:Vec<String>=Vec::new();
            for (i,_) in list.iter().enumerate(){
                let child_node=self.child_node(node,adj,&["anyOf",&i.to_string()]);
                let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/anyOf/{}",eval_path,i), dyn_scope, stack);
                if out.valid{ any_valid=true; branch_evaluated_props.extend(out.evaluated_props.clone()); branch_evaluated_items.extend(out.evaluated_items.clone()); children.push(out.unit); }
                else { all_branch_errors.extend(out.errors.clone()); if !any_valid { /* keep failed children only if overall fails later */ children.push(out.unit); } else {
                    // if we already have a success, failed branches after should be ??? Original successful anyOf only includes successful branch(es) up to? It evaluates all? For annotations, they may stop at first success.
                    // Our loop continues evaluating but list should only include successful. We'll handle post-filter below.
                }}
            }
            // Original behavior: if any valid, details are only successful branches (the first successful? It included only branch 1 in earlier 2-branch case where branch0 failed, branch1 success). If multiple succeed, does it include all successes or first? Probe later. For now filter to valid children only when any_valid.
            // We need rebuild: children currently may include failed before success.
            // We'll recompute filtering based on valid flag of units
            if any_valid{
                children.retain(|u|u.valid);
                // But if multiple valid branches were evaluated, retain all valid (maybe upstream stops at first success, so only first valid would be present because evaluation short-circuits. To mimic short-circuit, keep only first valid)
                if children.len()>1{ children.truncate(1); }
                ku.valid=true;
                valid&=true;
                evaluated_props.extend(branch_evaluated_props); evaluated_items.extend(branch_evaluated_items);
                // no errors
            } else {
                ku.valid=false;
                valid&=false;
                errors.push(format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", fmt_instance(instance)));
            }
            ku.details=children;
            ordered_units.push((111,ku));
        }
        // oneOf
        if let Some(Value::Array(list))=obj.get("oneOf"){
            let mut ku=Unit::new(format!("{}/oneOf",eval_path), inst_path.clone(), self.keyword_loc(adj,"oneOf"), true);
            let mut children=Vec::new(); let mut valid_count=0; let mut single_evaluated_props=BTreeSet::new(); let mut single_evaluated_items=BTreeSet::new();
            for (i,_) in list.iter().enumerate(){
                let child_node=self.child_node(node,adj,&["oneOf",&i.to_string()]);
                let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/oneOf/{}",eval_path,i), dyn_scope, stack);
                if out.valid{ valid_count+=1; if valid_count==1{ single_evaluated_props=out.evaluated_props.clone(); single_evaluated_items=out.evaluated_items.clone(); } }
                children.push(out.unit);
            }
            if valid_count==1{
                ku.valid=true;
                // details: only valid branch? Original oneOf success included only successful branch.
                children.retain(|u|u.valid);
                evaluated_props.extend(single_evaluated_props); evaluated_items.extend(single_evaluated_items);
            } else if valid_count==0{
                ku.valid=false; valid&=false;
                errors.push(format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", fmt_instance(instance)));
                // children remain all failed
            } else {
                ku.valid=false; valid&=false;
                let msg_text=format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", fmt_instance(instance));
                // list error value different
                let mut em=BTreeMap::new(); em.insert("oneOf".into(), ErrorVal::Single("more than one subschema succeeded".to_string()));
                ku.errors=Some(em);
                errors.push(msg_text);
                // children remain all (valid ones)
            }
            ku.details=children;
            ordered_units.push((112,ku));
        }
        // not
        if let Some(not_schema)=obj.get("not"){
            let child_node=self.child_node(node,adj,&["not"]);
            // evaluate without keeping unit details (not is leaf)
            let out=self.eval_node(&child_node, instance, inst_path.clone(), format!("{}/not",eval_path), dyn_scope, stack);
            let v=!out.valid;
            let mut ku=Unit::new(format!("{}/not",eval_path), inst_path.clone(), self.keyword_loc(adj,"not"), v);
            let mut errs=vec![];
            if !v{
                let msg=format!("{} is not allowed for {}", fmt_instance(not_schema), fmt_instance(instance));
                let mut em=BTreeMap::new(); em.insert("not".into(), ErrorVal::Single(msg.clone())); ku.errors=Some(em); errs.push(msg);
            }
            ordered_units.push((113,ku));
            valid&=v; errors.extend(errs);
        }

        // if / then / else group
        if obj.contains_key("if") && (obj.contains_key("then") || obj.contains_key("else") || true){
            // group even if only if
            // Evaluate if
            let if_node=self.child_node(node,adj,&["if"]);
            let if_out=self.eval_node(&if_node, instance, inst_path.clone(), format!("{}/if",eval_path), dyn_scope, stack);
            let mut group_unit=Unit::new(format!("{}/if",eval_path), inst_path.clone(), self.keyword_loc(adj,"if"), true);
            let mut group_details:Vec<Unit>=Vec::new();
            let mut group_valid=true; let mut group_errors:Vec<String>=Vec::new();
            if if_out.valid{
                group_details.push(if_out.unit.clone());
                evaluated_props.extend(if_out.evaluated_props.clone()); evaluated_items.extend(if_out.evaluated_items.clone());
                if let Some(_then_schema)=obj.get("then"){
                    let then_node=self.child_node(node,adj,&["then"]);
                    let then_out=self.eval_node(&then_node, instance, inst_path.clone(), format!("{}/then",eval_path), dyn_scope, stack);
                    group_valid&=then_out.valid; group_errors.extend(then_out.errors.clone()); group_details.push(then_out.unit);
                    if then_out.valid{ evaluated_props.extend(then_out.evaluated_props.clone()); evaluated_items.extend(then_out.evaluated_items.clone()); }
                }
            } else {
                // if failed, its units are suppressed (observed)
                if let Some(_else_schema)=obj.get("else"){
                    let else_node=self.child_node(node,adj,&["else"]);
                    let else_out=self.eval_node(&else_node, instance, inst_path.clone(), format!("{}/else",eval_path), dyn_scope, stack);
                    group_valid&=else_out.valid; group_errors.extend(else_out.errors.clone()); group_details.push(else_out.unit);
                    if else_out.valid{ evaluated_props.extend(else_out.evaluated_props.clone()); evaluated_items.extend(else_out.evaluated_items.clone()); }
                }
            }
            group_unit.valid=group_valid; group_unit.details=group_details;
            ordered_units.push((120,group_unit));
            valid&=group_valid; errors.extend(group_errors);
        } else {
            // then/else alone ignored
        }

        // unevaluatedProperties / Items (need evaluated sets up to this point excluding unevaluated themselves)
        // snapshot evaluated
        let evaluated_props_snapshot=evaluated_props.clone();
        let evaluated_items_snapshot=evaluated_items.clone();
        if let Some(un_schema)=obj.get("unevaluatedProperties"){
            if draft==Draft::D2019 || draft==Draft::D2020 {
                if let Some(inst_obj)=obj_instance{
                    let remaining:Vec<String>=inst_obj.keys().filter(|k|!evaluated_props_snapshot.contains(*k)).cloned().collect();
                    // evaluate schema on remaining
                    let mut failing:Vec<String>=Vec::new();
                    let mut child_units:Vec<Unit>=Vec::new(); let mut u_valid=true;
                    for name in &remaining{
                        let val=&inst_obj[name];
                        let child_node=self.child_node(node,adj,&["unevaluatedProperties"]);
                        let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path, uri::escape_pointer_token(name)), format!("{}/unevaluatedProperties",eval_path), dyn_scope, stack);
                        if !out.valid{ failing.push(name.clone()); }
                        child_units.push(out.unit);
                    }
                    // If schema is Bool false, failing = all remaining (eval will fail)
                    // Build keyword unit
                    let mut ku=Unit::new(format!("{}/unevaluatedProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"unevaluatedProperties"), true);
                    let mut errs=vec![];
                    if !failing.is_empty(){
                        u_valid=false;
                        let msg=format!("Unevaluated properties are not allowed ({}{})", quoted_list_names(&failing), ""); // fix
                        let msg=unevaluated_properties_message(&failing);
                        let mut em=BTreeMap::new(); em.insert("unevaluatedProperties".into(), ErrorVal::Single(msg.clone())); ku.errors=Some(em); errs.push(msg);
                    }
                    ku.valid=u_valid;
                    // details: only child units when ? Original: keyword unit then child units as separate details of root (list flatten shows keyword then its applications as siblings? In our tree, ku.details=child_units will flatten after ku, matches list. For hierarchical, original might nest.
                    // But if un_schema is schema, child_units are applications - include them as details only if there are any? Original failing case included applications. Valid case with schema also includes.
                    // If bool false, child units are false schema units - original included one per... For {"a":1} it included keyword + one false unit (same path). Good.
                    // If remaining empty, no details
                    ku.details=child_units;
                    ordered_units.push((130,ku));
                    valid&=u_valid; errors.extend(errs);
                    // unevaluated props evaluated by unevaluatedProperties itself? For nested... add remaining that passed? Not needed above level unless this node is branch: if u_valid, all remaining are now evaluated
                    if u_valid{ for n in remaining{ evaluated_props.insert(n); } }
                } else {
                    let ku=Unit::new(format!("{}/unevaluatedProperties",eval_path), inst_path.clone(), self.keyword_loc(adj,"unevaluatedProperties"), true);
                    ordered_units.push((130,ku));
                }
            }
        }
        if let Some(un_schema)=obj.get("unevaluatedItems"){
            if draft==Draft::D2019 || draft==Draft::D2020 {
                if let Some(inst_arr)=arr_instance{
                    let remaining:Vec<usize>=(0..inst_arr.len()).filter(|i|!evaluated_items_snapshot.contains(i)).collect();
                    let mut failing_indices:Vec<usize>=Vec::new();
                    let mut failing_values:Vec<Value>=Vec::new();
                    let mut child_units=Vec::new(); let mut u_valid=true;
                    for &i in &remaining{
                        let val=&inst_arr[i];
                        let child_node=self.child_node(node,adj,&["unevaluatedItems"]);
                        let out=self.eval_node(&child_node, val, format!("{}/{}",inst_path,i), format!("{}/unevaluatedItems",eval_path), dyn_scope, stack);
                        if !out.valid{ failing_indices.push(i); failing_values.push(val.clone()); }
                        child_units.push(out.unit);
                    }
                    let mut ku=Unit::new(format!("{}/unevaluatedItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"unevaluatedItems"), true);
                    let mut errs=vec![];
                    if !failing_indices.is_empty(){
                        u_valid=false;
                        let msg=unevaluated_items_message(&failing_values);
                        let mut em=BTreeMap::new(); em.insert("unevaluatedItems".into(), ErrorVal::Single(msg.clone())); ku.errors=Some(em); errs.push(msg);
                    }
                    ku.valid=u_valid; ku.details=child_units;
                    ordered_units.push((131,ku));
                    valid&=u_valid; errors.extend(errs);
                    if u_valid{ for i in remaining{ evaluated_items.insert(i); } }
                    let _=un_schema;
                } else {
                    let ku=Unit::new(format!("{}/unevaluatedItems",eval_path), inst_path.clone(), self.keyword_loc(adj,"unevaluatedItems"), true);
                    ordered_units.push((131,ku));
                }
            }
        }

        // $ref / $dynamicRef
        if has_ref {
            // already handled for old drafts; for 2019+ evaluate as applicator
            let ref_out=self.eval_ref_keyword(node, adj, obj.get("$ref").unwrap(), instance, &inst_path, &eval_path, dyn_scope, stack, false);
            if let Some(u)=ref_out.unit_opt{ ordered_units.push((140,u)); }
            valid&=ref_out.valid; errors.extend(ref_out.errors);
            if ref_out.valid{ evaluated_props.extend(ref_out.evaluated_props); evaluated_items.extend(ref_out.evaluated_items); }
        }
        if has_dyn_ref {
            if draft==Draft::D2020 {
                let ref_out=self.eval_ref_keyword(node, adj, obj.get("$dynamicRef").unwrap(), instance, &inst_path, &eval_path, dyn_scope, stack, true);
                if let Some(u)=ref_out.unit_opt{ ordered_units.push((141,u)); }
                valid&=ref_out.valid; errors.extend(ref_out.errors);
                if ref_out.valid{ evaluated_props.extend(ref_out.evaluated_props); evaluated_items.extend(ref_out.evaluated_items); }
            }
        }
        if draft==Draft::D2019 && has_rec_ref {
            let ref_out=self.eval_ref_keyword(node, adj, obj.get("$recursiveRef").unwrap(), instance, &inst_path, &eval_path, dyn_scope, stack, true);
            if let Some(u)=ref_out.unit_opt{ ordered_units.push((141,u)); }
            valid&=ref_out.valid; errors.extend(ref_out.errors);
            if ref_out.valid{ evaluated_props.extend(ref_out.evaluated_props); evaluated_items.extend(ref_out.evaluated_items); }
        }

        // assemble root
        ordered_units.sort_by_key(|(r,_)|*r);
        let mut root_unit=Unit::new(eval_path.clone(), inst_path.clone(), self.schema_loc(adj), valid);
        root_unit.details=ordered_units.into_iter().map(|(_,u)|u).collect();
        // annotations
        if let Some(ann)=self.node_annotations(obj,draft){
            if valid{ root_unit.annotations=Some(ann);} else { root_unit.dropped=Some(ann); }
        }
        // If root invalid but some errors missing etc, errors already collected
        // final valid recomputed as root_unit.valid (already valid variable)
        Outcome{valid, unit:root_unit, errors, evaluated_props, evaluated_items, annotations_value:None}
    }

    fn eval_type(&self, tv:&Value, instance:&Value, eval_path:&str, loc:&str, inst_path:&str)->(Unit,bool,Vec<String>){
        // tv string or array
        let mut valid=false;
        let mut msg:Option<String>=None;
        match tv{
            Value::String(t)=>{ valid=type_matches(t,instance); if !valid{ msg=Some(err_type_single(instance,t)); } }
            Value::Array(arr)=>{
                let mut types:Vec<String>=arr.iter().filter_map(|v|v.as_str().map(|s|s.to_string())).collect();
                valid=types.iter().any(|t|type_matches(t,instance));
                if !valid{
                    types.sort(); types.dedup();
                    if types.len()==1{ msg=Some(err_type_single(instance,&types[0])); }
                    else {
                        let list=types.iter().map(|t|format!("\"{}\"",t)).collect::<Vec<_>>().join(", ");
                        msg=Some(format!("{} is not of types {}", fmt_instance(instance), list));
                    }
                }
            }
            _=>{ valid=true; }
        }
        let mut u=Unit::new(eval_path.to_string(), inst_path.to_string(), loc.to_string(), valid);
        let mut errs=vec![];
        if let Some(m)=msg{ let mut em=BTreeMap::new(); em.insert("type".into(), ErrorVal::Single(m.clone())); u.errors=Some(em); errs.push(m); }
        (u,valid,errs)
    }

    fn eval_dependent_required(&self, node:&CNode, adj:&Adjusted, deps:&Map<String,Value>, instance:&Value, inst_path:&str, eval_path:&str, kw:&str, _rank:i32, _dyn_scope:&mut Vec<DynamicFrame>, _stack:&mut Vec<(NodeKey,String,usize)>)->(Option<Unit>,bool,Vec<String>){
        if let Value::Object(inst_obj)=instance{
            let mut ku=Unit::new(format!("{}/{}",eval_path,kw), inst_path.to_string(), self.keyword_loc(adj,kw), true);
            let mut children=Vec::new(); let mut v=true; let mut errs=Vec::new();
            for (name,req) in deps.iter(){
                if inst_obj.contains_key(name){
                    if let Value::Array(arr)=req{
                        // synthetic subschema unit duplicate path
                        let mut sub_unit=Unit::new(format!("{}/{}",eval_path,kw), inst_path.to_string(), self.keyword_loc(adj,kw), true);
                        let missing:Vec<String>=arr.iter().filter_map(|x|x.as_str()).filter(|n|!inst_obj.contains_key(*n)).map(|s|s.to_string()).collect();
                        let sub_valid=missing.is_empty();
                        let mut leaf=Unit::new(format!("{}/{}/0",eval_path,kw), inst_path.to_string(), format!("{}/0", self.keyword_loc(adj,kw)), sub_valid);
                        if !sub_valid{
                            let msgs:Vec<String>=missing.iter().map(|n|format!("\"{}\" is a required property",n)).collect();
                            let mut em=BTreeMap::new();
                            if msgs.len()==1{ em.insert("required".into(), ErrorVal::Single(msgs[0].clone())); } else { em.insert("required".into(), ErrorVal::Multi(msgs.clone())); }
                            leaf.errors=Some(em); errs.extend(msgs);
                        }
                        sub_unit.valid=sub_valid; sub_unit.details=vec![leaf];
                        v&=sub_valid;
                        children.push(sub_unit);
                    }
                }
            }
            ku.valid=v; ku.details=children;
            (Some(ku),v,errs)
        } else {
            let ku=Unit::new(format!("{}/{}",eval_path,kw), inst_path.to_string(), self.keyword_loc(adj,kw), true);
            (Some(ku),true,vec![])
        }
    }

    fn node_annotations(&self, obj:&Map<String,Value>, draft:Draft)->Option<Value>{
        let mut m=Map::new();
        for (k,v) in obj.iter(){
            if is_annotation_key(k) || !is_known_keyword(k,draft){ m.insert(k.clone(), v.clone()); }
        }
        if m.is_empty(){ None } else { Some(Value::Object(m)) }
    }

    fn eval_ref_keyword(&self, node:&CNode, adj:&Adjusted, ref_val:&Value, instance:&Value, inst_path:&str, eval_path:&str, dyn_scope:&mut Vec<DynamicFrame>, stack:&mut Vec<(NodeKey,String,usize)>, dynamic:bool)->RefOutcome{
        let kw = if dynamic { if adj.draft==Draft::D2019 {"$recursiveRef"} else {"$dynamicRef"} } else {"$ref"};
        let eval_p = format!("{}/{}", eval_path, kw);
        let Some(ref_str)=ref_val.as_str() else {
            return RefOutcome{valid:true, unit_opt:None, errors:vec![], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new()};
        };
        // resolve (errors should have been pre-checked in build; during meta eval they exist)
        let resolved = match self.registry.resolve_ref(&adj.node, ref_str, dyn_scope){
            Ok(r)=>r, Err(e)=>{
                // In evaluation context (eg meta validator), unresolved may be reported as error? Return invalid with message
                let mut u=Unit::new(eval_p.clone(), inst_path.to_string(), self.keyword_loc(adj,kw), false);
                let mut em=BTreeMap::new(); em.insert(kw.to_string(), ErrorVal::Single(e.clone())); u.errors=Some(em);
                return RefOutcome{valid:false, unit_opt:Some(u), errors:vec![e], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new()};
            }
        };
        let mut target = resolved.cnode;
        // Dynamic resolution
        if dynamic {
            // if fragment is plain name, look through dyn_scope from innermost out for dynamic anchor with that name
            let frag = resolved.fragment.clone();
            if !frag.is_empty() && !frag.starts_with('/'){
                // search scope
                for frame in dyn_scope.iter().rev(){
                    // frame node is a schema resource entered via ref; check its dynamic anchors
                    // The frame's document/base: dynamic anchor uri = frame node's effective base + #frag
                    let base = self.registry.effective_base(&frame.node);
                    let key=format!("{}#{}", base, frag);
                    if let Some((d,p))=self.registry.dynamic_anchors.get(&key){
                        // check that this anchor is in a different resource? Use it
                        let (parent_base, loc_uri, _loc_root)=self.registry.loc_context_for(*d,p);
                        target=CNode{doc:*d, ptr:p.clone(), base_uri:parent_base, loc_uri:loc_uri.clone(), loc_root:p.clone(), draft:self.registry.docs[*d].draft};
                        break;
                    }
                    // Also if frame node itself document contains dynamic anchor? Search registry anchors for any doc with same base? Simplified above uses frame base.
                    // Also recursive: if frame node has $recursiveAnchor true etc skip
                }
            }
        }
        // self ref suppression: if target is the current node (adj.node)
        if target.key()==adj.node.key(){
            return RefOutcome{valid:true, unit_opt:None, errors:vec![], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new()};
        }
        // recursion guard: count occurrences of target key with same instance in stack
        let count = stack.iter().filter(|(k,ip,_)| k==&target.key() && ip==inst_path).count();
        // Build target schema location for ref unit
        let target_adj = self.adjust(&target);
        let target_loc = self.schema_loc(&target_adj);
        if count>=3 {
            let u=Unit::new(eval_p.clone(), inst_path.to_string(), target_loc, true);
            return RefOutcome{valid:true, unit_opt:Some(u), errors:vec![], evaluated_props:BTreeSet::new(), evaluated_items:BTreeSet::new()};
        }
        // push dynamic frame: this target is entered; dynamic scope should contain nodes along ref chain
        // For dynamicRef resolution, scope is stack of schema resources visited. We'll push target frame before evaluating, pop after.
        dyn_scope.push(DynamicFrame{node:target.clone(), name_uri:target_loc.clone()});
        let out=self.eval_node(&target, instance, inst_path.to_string(), eval_p.clone(), dyn_scope, stack);
        dyn_scope.pop();
        // Ref unit is target's unit but with eval path = eval_p and schema_loc = target_loc, details = target's keyword units (its details)
        // out.unit already has eval_path=eval_p (since we passed eval_p) and schema_loc=target_loc (adjust uses target loc)
        // However out.unit is the target node unit; that's exactly the $ref unit in output.
        RefOutcome{valid:out.valid, unit_opt:Some(out.unit), errors:out.errors, evaluated_props:out.evaluated_props, evaluated_items:out.evaluated_items}
    }
}

#[derive(Clone)]
struct Adjusted { node:CNode, value:Value, base_uri:String, loc_uri:String, loc_root:Pointer, draft:Draft }

struct RefOutcome{ valid:bool, unit_opt:Option<Unit>, errors:Vec<String>, evaluated_props:BTreeSet<String>, evaluated_items:BTreeSet<usize> }

fn make_leaf(eval_path:String, inst_path:String, loc:String, valid:bool, key:&str, msg:Option<String>)->(Unit,Vec<String>){
    let mut u=Unit::new(eval_path, inst_path, loc, valid);
    let mut errs=vec![];
    if let Some(m)=msg{ let mut em=BTreeMap::new(); em.insert(key.to_string(), ErrorVal::Single(m.clone())); u.errors=Some(em); errs.push(m); }
    (u,errs)
}

fn as_usize(v:&Value)->Option<usize>{
    match v{
        Value::Number(n)=>{
            if let Some(u)=n.as_u64(){ Some(u as usize) } else if let Some(i)=n.as_i64(){ if i>=0{Some(i as usize)}else{None}} else {
                let d=num::decimal_of(v)?; if num::is_integer(&d) && !d.neg { d.to_f64() .try_into().ok().or(Some(usize::MAX)) } else {None}
            }
        }
        _=>None
    }
}

fn type_matches(t:&str, inst:&Value)->bool{
    match t{
        "string"=>matches!(inst,Value::String(_)),
        "number"=>matches!(inst,Value::Number(_)),
        "integer"=>num::value_is_integer(inst),
        "boolean"=>matches!(inst,Value::Bool(_)),
        "object"=>matches!(inst,Value::Object(_)),
        "array"=>matches!(inst,Value::Array(_)),
        "null"=>matches!(inst,Value::Null),
        _=>false,
    }
}

fn enum_message(inst:&Value,cands:&[Value])->String{
    match cands.len(){
        0=>format!("{} is not one of ", fmt_instance(inst)),
        1=>format!("{} is not one of {}", fmt_instance(inst), fmt_instance(&cands[0])),
        2=>format!("{} is not one of {} or {}", fmt_instance(inst), fmt_instance(&cands[0]), fmt_instance(&cands[1])),
        n=>format!("{} is not one of {}, {} or {} other candidates", fmt_instance(inst), fmt_instance(&cands[0]), fmt_instance(&cands[1]), n-2),
    }
}

fn additional_properties_message(names:&[String])->String{
    if names.len()==1{ format!("Additional properties are not allowed ('{}' was unexpected)", names[0]) }
    else { format!("Additional properties are not allowed ({} were unexpected)", names.iter().map(|n|format!("'{}'",n)).collect::<Vec<_>>().join(", ")) }
}
fn additional_items_message(values:&[&Value])->String{
    let vals:Vec<String>=values.iter().map(|v|fmt_instance(v)).collect();
    if vals.len()==1{ format!("Additional items are not allowed ({} was unexpected)", vals[0]) }
    else { format!("Additional items are not allowed ({} were unexpected)", vals.join(", ")) }
}
fn unevaluated_properties_message(names:&[String])->String{
    if names.len()==1{ format!("Unevaluated properties are not allowed ('{}' was unexpected)", names[0]) }
    else { format!("Unevaluated properties are not allowed ({} were unexpected)", names.iter().map(|n|format!("'{}'",n)).collect::<Vec<_>>().join(", ")) }
}
fn unevaluated_items_message(values:&[Value])->String{
    let vals:Vec<String>=values.iter().map(|v|format!("'{}'",fmt_instance(v))).collect();
    if vals.len()==1{ format!("Unevaluated items are not allowed ({} was unexpected)", vals[0]) }
    else { format!("Unevaluated items are not allowed ({} were unexpected)", vals.join(", ")) }
}

pub fn is_annotation_key(k:&str)->bool{
    matches!(k,"title"|"description"|"default"|"examples"|"readOnly"|"writeOnly"|"deprecated"|"$comment"|"contentEncoding"|"contentMediaType"|"contentSchema"|"$vocabulary")
}
pub fn is_known_keyword(k:&str, draft:Draft)->bool{
    // Keywords recognized (not annotations) for this draft
    let base = ["type","enum","allOf","anyOf","oneOf","not","properties","patternProperties","additionalProperties","items","minimum","maximum","multipleOf","minLength","maxLength","pattern","minItems","maxItems","uniqueItems","minProperties","maxProperties","required","dependencies","format","title","description","default","examples","readOnly","$ref","$schema","$id","$defs","definitions","contentEncoding","contentMediaType"];
    // We will handle via match for draft-specific
    match k {
        "title"|"description"|"default"|"examples"|"readOnly"|"writeOnly"|"deprecated"|"$comment"|"contentEncoding"|"contentMediaType"|"contentSchema"|"$vocabulary" => false, // annotation keys handled separately (they are in annotation map, so known check should return true to avoid double? Our node_annotations adds if is_annotation OR !known. So returning false would also add. To avoid duplicate logic, return true here and annotation check drives.
        _=>{}
    }
    let _=base;
    // define sets
    let common: &[&str]=&["type","enum","allOf","anyOf","oneOf","not","properties","patternProperties","additionalProperties","additionalItems","items","minimum","maximum","multipleOf","minLength","maxLength","pattern","minItems","maxItems","uniqueItems","minProperties","maxProperties","required","dependencies","format","$ref","$schema"];
    if common.contains(&k){ return true; }
    match draft{
        Draft::D4=>{
            matches!(k,"exclusiveMinimum"|"exclusiveMaximum"|"id"|"definitions")
        }
        Draft::D6=>{
            matches!(k,"exclusiveMinimum"|"exclusiveMaximum"|"const"|"contains"|"propertyNames"|"$id"|"examples"|"definitions")
        }
        Draft::D7=>{
            matches!(k,"exclusiveMinimum"|"exclusiveMaximum"|"const"|"contains"|"propertyNames"|"$id"|"if"|"then"|"else"|"contentMediaType"|"contentEncoding"|"definitions"|"examples"|"$comment")
        }
        Draft::D2019=>{
            matches!(k,"exclusiveMinimum"|"exclusiveMaximum"|"const"|"contains"|"propertyNames"|"$id"|"$anchor"|"$defs"|"if"|"then"|"else"|"dependentRequired"|"dependentSchemas"|"unevaluatedItems"|"unevaluatedProperties"|"minContains"|"maxContains"|"$recursiveRef"|"$recursiveAnchor"|"$vocabulary"|"contentSchema"|"definitions")
        }
        Draft::D2020=>{
            matches!(k,"exclusiveMinimum"|"exclusiveMaximum"|"const"|"contains"|"propertyNames"|"$id"|"$anchor"|"$dynamicRef"|"$dynamicAnchor"|"$defs"|"if"|"then"|"else"|"dependentRequired"|"dependentSchemas"|"unevaluatedItems"|"unevaluatedProperties"|"minContains"|"maxContains"|"prefixItems"|"$vocabulary"|"contentSchema")
        }
    }
}

// -------- Building validators --------
pub struct Builder {
    pub cfg: RetrieverConfig,
    pub forced_draft: Option<Draft>,
    pub assert_format: bool,
}

pub fn build_meta_validator_for_draft(draft:Draft, cfg:&RetrieverConfig)->Result<Validator,String>{
    // Build from embedded meta docs
    let mut reg=Registry::new(cfg.clone());
    match draft{
        Draft::D2020=>{
            for (uri,doc) in crate::meta::meta2020_docs(){ reg.add_document(uri,doc,Draft::D2020)?; }
            let root_idx=reg.by_uri["https://json-schema.org/draft/2020-12/schema"];
            let root=CNode{doc:root_idx, ptr:vec![], base_uri:"https://json-schema.org/draft/2020-12/schema".into(), loc_uri:"https://json-schema.org/draft/2020-12/schema".into(), loc_root:vec![], draft:Draft::D2020};
            Ok(Validator{registry:reg, root, assert_format:false})
        }
        Draft::D2019=>{
            for (uri,doc) in crate::meta2019::meta2019_docs(){ reg.add_document(uri,doc,Draft::D2019)?; }
            let root_uri="https://json-schema.org/draft/2019-09/schema";
            let root_idx=reg.by_uri[root_uri];
            let root=CNode{doc:root_idx, ptr:vec![], base_uri:root_uri.into(), loc_uri:root_uri.into(), loc_root:vec![], draft:Draft::D2019};
            Ok(Validator{registry:reg, root, assert_format:false})
        }
        Draft::D7|Draft::D6|Draft::D4=>{
            let (uri,doc)=match draft{ Draft::D7=>crate::meta_old::meta7(), Draft::D6=>crate::meta_old::meta6(), _=>crate::meta_old::meta4() };
            reg.add_document(uri.clone(),doc,draft)?;
            let root_idx=reg.by_uri[&uri];
            let root=CNode{doc:root_idx, ptr:vec![], base_uri:uri.clone(), loc_uri:uri, loc_root:vec![], draft};
            Ok(Validator{registry:reg, root, assert_format:false})
        }
    }
}

// Build a validator from an arbitrary schema document value (no meta validation of that schema itself except refs compile)
// Used for custom meta schemas
pub fn build_validator_unchecked(root_value:Value, root_base:String, draft:Draft, cfg:&RetrieverConfig, assert_format:bool)->Result<Validator,String>{
    let mut reg=Registry::new(cfg.clone());
    let idx=reg.add_document(root_base.clone(), root_value, draft)?;
    let (parent_base,loc_uri,loc_root)=reg.loc_context_for(idx,&vec![]);
    let root=CNode{doc:idx, ptr:vec![], base_uri:parent_base, loc_uri, loc_root, draft};
    let v=Validator{registry:reg, root, assert_format};
    // compile check reachable
    v.compile_check()?;
    Ok(v)
}
