pub enum MetaKind { Known(Draft), Custom{ validator: Validator, semantic_draft: Draft } }
pub struct MetaInfo { pub validator: Validator, pub semantic_draft: Draft }

pub fn determine_meta_validator(root:&Value, use_forced:Option<Draft>, cfg:&RetrieverConfig)->Result<MetaInfo,BuildError>{
    if let Some(d)=use_forced{
        let v=build_meta_validator_for_draft(d,cfg).map_err(|e|BuildError::msg(e))?;
        return Ok(MetaInfo{validator:v, semantic_draft:d});
    }
    if let Value::Object(obj)=root{
        if let Some(sv)=obj.get("$schema"){
            match sv {
                Value::String(s)=>{
                    if let Some(e)=uri::validate_uri_ref_err(s){ return Err(BuildError::msg(e)); }
                    if let Some(d)=detect_known_draft(s){
                        let v=build_meta_validator_for_draft(d,cfg).map_err(|e|BuildError::msg(e))?;
                        return Ok(MetaInfo{validator:v, semantic_draft:d});
                    }
                    // unknown -> retrieve
                    let nofrag=uri::without_fragment(s);
                    match retrieve_resource(&nofrag,cfg){
                        Ok(doc)=>{
                            // circular detection: doc's $schema resolves to itself
                            if let Value::Object(dobj)=&doc{
                                if let Some(ms)=dobj.get("$schema").and_then(|x|x.as_str()){
                                    let resolved=uri::resolve_uri(&nofrag, ms);
                                    if uri::without_fragment(&resolved)==nofrag {
                                        return Err(BuildError::msg(format!("Circular meta-schema reference detected at '{}'", s)));
                                    }
                                }
                            }
                            let sem_draft=declared_draft(&doc).unwrap_or(Draft::D2020);
                            // build validator from retrieved doc unchecked
                            let v=build_validator_unchecked(doc, nofrag.clone(), sem_draft, cfg, false).map_err(|e|BuildError::msg(e))?;
                            return Ok(MetaInfo{validator:v, semantic_draft:sem_draft});
                        }
                        Err(e)=>{
                            return Err(BuildError::msg(resource_error(s,&e)));
                        }
                    }
                }
                _=>{
                    // non-string, meta will fail; use default
                    let v=build_meta_validator_for_draft(Draft::D2020,cfg).map_err(|e|BuildError::msg(e))?;
                    return Ok(MetaInfo{validator:v, semantic_draft:Draft::D2020});
                }
            }
        }
    }
    let v=build_meta_validator_for_draft(Draft::D2020,cfg).map_err(|e|BuildError::msg(e))?;
    Ok(MetaInfo{validator:v, semantic_draft:Draft::D2020})
}

// Build user validator. If skip_meta, don't perform meta validation (meta phase already done)
pub fn build_user_validator(root:Value, root_base:String, builder:&Builder, skip_meta:bool)->Result<Validator,BuildError>{
    let cfg=&builder.cfg;
    // provisional draft
    let declared = declared_draft(&root);
    let provisional = builder.forced_draft.or(declared).unwrap_or(Draft::D2020);
    let mut reg=Registry::new(cfg.clone());
    let root_idx = reg.add_document(root_base.clone(), root.clone(), provisional).map_err(|e|BuildError::msg(e))?;
    // determine draft/meta
    let (draft, meta_validator_opt): (Draft, Option<Validator>) = if skip_meta {
        // semantic draft from schema or default (forced ignored in this phase as per schema-only behaviour)
        let d=declared.unwrap_or_else(||{
            // if $schema unknown custom, try determine from its meta doc; else 2020
            if let Value::Object(o)=&root{ if let Some(s)=o.get("$schema").and_then(|x|x.as_str()){ if detect_known_draft(s).is_none(){
                let nofrag=uri::without_fragment(s);
                if let Ok(doc)=retrieve_resource(&nofrag,cfg){ return declared_draft(&doc).unwrap_or(Draft::D2020); }
            }}}
            Draft::D2020
        });
        (d, None)
    } else if let Some(fd)=builder.forced_draft {
        let mv=build_meta_validator_for_draft(fd,cfg).map_err(|e|BuildError::msg(e))?;
        (fd, Some(mv))
    } else if let Value::Object(obj)=&root{
        if let Some(sv)=obj.get("$schema"){
            match sv{
                Value::String(s)=>{
                    if let Some(e)=uri::validate_uri_ref_err(s){ return Err(BuildError::msg(e)); }
                    if let Some(d)=detect_known_draft(s){
                        let mv=build_meta_validator_for_draft(d,cfg).map_err(|e|BuildError::msg(e))?;
                        (d, Some(mv))
                    } else {
                        // retrieve custom meta to determine draft
                        let nofrag=uri::without_fragment(s);
                        match retrieve_resource(&nofrag,cfg){
                            Ok(doc)=>{
                                let d=declared_draft(&doc).unwrap_or(Draft::D2020);
                                let mv=build_meta_validator_for_draft(d,cfg).map_err(|e|BuildError::msg(e))?;
                                (d, Some(mv))
                            }
                            Err(_)=>{
                                return Err(BuildError{message:format!("Unknown meta-schema: '{}'. Custom meta-schemas must be registered in the registry before use", s), is_meta:false, meta_validator:None, meta_first_error:None});
                            }
                        }
                    }
                }
                _=>{
                    let mv=build_meta_validator_for_draft(Draft::D2020,cfg).map_err(|e|BuildError::msg(e))?;
                    (Draft::D2020, Some(mv))
                }
            }
        } else {
            let mv=build_meta_validator_for_draft(Draft::D2020,cfg).map_err(|e|BuildError::msg(e))?;
            (Draft::D2020, Some(mv))
        }
    } else {
        let mv=build_meta_validator_for_draft(Draft::D2020,cfg).map_err(|e|BuildError::msg(e))?;
        (Draft::D2020, Some(mv))
    };
    // update root doc draft
    reg.docs[root_idx].draft=draft;
    let (parent_base,loc_uri,loc_root)=reg.loc_context_for(root_idx,&vec![]);
    let root_node=CNode{doc:root_idx, ptr:vec![], base_uri:parent_base, loc_uri, loc_root, draft};
    let mut validator=Validator{registry:reg, root:root_node, assert_format:builder.assert_format};
    if !skip_meta{
        if let Some(mv)=meta_validator_opt{
            let outcome=mv.apply(&root);
            if !outcome.valid{
                let first=outcome.errors.get(0).cloned().unwrap_or_else(||"".to_string());
                return Err(BuildError{message:first.clone(), is_meta:true, meta_validator:Some(Box::new(mv)), meta_first_error:Some(first)});
            }
            // keep meta validator dropped (need it only on error)
            let _=mv;
        }
    }
    validator.compile_check().map_err(|e|BuildError::msg(e))?;
    Ok(validator)
}
