// ---------- Compilation checks & builder ----------
impl Validator {
    pub fn compile_check(&self)->Result<(),String>{
        // Phase A: traverse reachable graph resolving refs
        let mut visited: HashSet<NodeKey>=HashSet::new();
        let mut order: Vec<CNode>=Vec::new();
        let mut stack: Vec<CNode>=vec![self.root.clone()];
        while let Some(node)=stack.pop(){
            let key=node.key();
            if visited.contains(&key){ continue; }
            visited.insert(key);
            order.push(node.clone());
            let adj=self.adjust(&node);
            if let Value::Object(obj)=&adj.value{
                // children in priority-ish order for traversal
                let children=self.compile_children(&node,&adj);
                // refs resolved here
                for kw in ["$ref","$dynamicRef","$recursiveRef"]{
                    if let Some(rv)=obj.get(kw){
                        if let Some(rs)=rv.as_str(){
                            // validate
                            if let Some(e)=uri::validate_uri_ref_err(rs){ return Err(e); }
                            // resolve target
                            // For dynamic/recursive, resolution may fall back if anchor missing? Use resolve_ref
                            let target=self.registry.resolve_ref(&adj.node, rs, &[])?;
                            // push target
                            stack.push(target.cnode);
                        }
                    }
                }
                // push children reversed so earlier priority processed first in DFS (stack LIFO)
                for c in children.into_iter().rev(){ stack.push(c); }
            }
        }
        // Phase B: pattern checks etc in order visited
        for node in &order{
            let adj=self.adjust(node);
            if let Value::Object(obj)=&adj.value{
                let draft=adj.draft;
                if draft==Draft::D4{
                    if obj.contains_key("exclusiveMinimum") && !obj.contains_key("minimum"){ return Err("\"minimum\" is a required property".to_string()); }
                    if obj.contains_key("exclusiveMaximum") && !obj.contains_key("maximum"){ return Err("\"maximum\" is a required property".to_string()); }
                }
                if let Some(pv)=obj.get("pattern"){
                    if let Some(pat)=pv.as_str(){
                        if fancy_regex::Regex::new(pat).is_err(){ return Err(format!("{} is not a \"regex\"", num::format_json(pv))); }
                    }
                }
                if let Some(Value::Object(pats))=obj.get("patternProperties"){
                    // only if keyword active in draft (patternProperties exists all drafts)
                    for (pat,sub) in pats{
                        if fancy_regex::Regex::new(pat).is_err(){ return Err(format!("{} is not a \"regex\"", num::format_json(sub))); }
                    }
                }
            }
        }
        Ok(())
    }

    fn compile_children(&self, node:&CNode, adj:&Adjusted)->Vec<CNode>{
        let obj=match &adj.value{ Value::Object(m)=>m,_=>return vec![]};
        let draft=adj.draft;
        let mut out:Vec<CNode>=Vec::new();
        let mut push_child=|out:&mut Vec<CNode>, tokens:&[&str]|{
            out.push(self.child_node(node, adj, tokens));
        };
        // priority order for traversal
        // properties
        if let Some(Value::Object(m))=obj.get("properties"){ for name in m.keys(){ push_child(&mut out,&["properties",name]); } }
        if let Some(Value::Object(m))=obj.get("patternProperties"){ for name in m.keys(){ push_child(&mut out,&["patternProperties",name]); } }
        if matches!(obj.get("additionalProperties"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["additionalProperties"]); }
        if draft!=Draft::D4 && matches!(obj.get("propertyNames"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["propertyNames"]); }
        // items / prefix
        match draft{
            Draft::D2020=>{
                if let Some(Value::Array(a))=obj.get("prefixItems"){ for i in 0..a.len(){ let s=i.to_string(); push_child(&mut out,&["prefixItems",&s]); } }
                if matches!(obj.get("items"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["items"]); }
            }
            Draft::D2019|Draft::D7|Draft::D6|Draft::D4=>{
                match obj.get("items"){
                    Some(Value::Array(a))=>{ for i in 0..a.len(){ let s=i.to_string(); push_child(&mut out,&["items",&s]); } }
                    Some(Value::Object(_)|Value::Bool(_))=>{ push_child(&mut out,&["items"]); }
                    _=>{}
                }
                if draft!=Draft::D2020 && obj.get("items").map(|v|v.is_array()).unwrap_or(false){
                    if matches!(obj.get("additionalItems"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["additionalItems"]); }
                }
            }
        }
        if draft!=Draft::D4 && matches!(obj.get("contains"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["contains"]); }
        if draft==Draft::D2019||draft==Draft::D2020 {
            if let Some(Value::Object(m))=obj.get("dependentSchemas"){ for name in m.keys(){ push_child(&mut out,&["dependentSchemas",name]); } }
        }
        if let Some(Value::Object(m))=obj.get("dependencies"){ for (name,sub) in m{ if matches!(sub,Value::Object(_)|Value::Bool(_)){ push_child(&mut out,&["dependencies",name]); } } }
        for kw in ["allOf","anyOf","oneOf"]{
            if let Some(Value::Array(a))=obj.get(kw){ for i in 0..a.len(){ let s=i.to_string(); push_child(&mut out,&[kw,&s]); } }
        }
        if matches!(obj.get("not"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["not"]); }
        if draft!=Draft::D4 && draft!=Draft::D6 {
            if matches!(obj.get("if"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["if"]); }
            if matches!(obj.get("then"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["then"]); }
            if matches!(obj.get("else"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["else"]); }
        }
        if draft==Draft::D2019||draft==Draft::D2020 {
            if matches!(obj.get("unevaluatedProperties"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["unevaluatedProperties"]); }
            if matches!(obj.get("unevaluatedItems"), Some(Value::Object(_)|Value::Bool(_))){ push_child(&mut out,&["unevaluatedItems"]); }
        }
        if draft==Draft::D2019||draft==Draft::D2020 {
            if let Some(Value::Object(m))=obj.get("$defs"){ for name in m.keys(){ /* $defs are not compiled unless referenced; skip */ let _=name; } }
        }
        out
    }
}

