use crate::validator::RetrieverConfig;
use serde_json::Value;
use std::io::{Read, Write};
use std::net::{TcpStream, ToSocketAddrs};
use std::time::{Duration, Instant};

pub fn fetch_json(url:&str, cfg:&RetrieverConfig)->Result<Value,String>{
    let mut current = url.to_string();
    let mut redirects=0usize;
    loop {
        let resp = fetch_once(&current, if redirects>0 { Some(url) } else { None }, cfg);
        match resp {
            FetchResult::Redirect(location)=>{
                if redirects>=10 {
                    return Err(format!("error following redirect for url ({})", url));
                }
                redirects+=1;
                current = crate::uri::resolve_uri(&current, &location);
                continue;
            }
            FetchResult::Body(body, final_url)=>{
                // parse json
                match serde_json::from_slice::<Value>(&body){
                    Ok(v)=>return Ok(v),
                    Err(_)=>{ return Err(format!("error decoding response body for url ({})", final_url)); }
                }
            }
            FetchResult::Error(kind, u)=>{
                // kind sending/following etc
                return Err(kind.replace("{url}", &u));
            }
        }
    }
}

enum FetchResult{ Redirect(String), Body(Vec<u8>, String), Error(String,String) }

fn parse_url(url:&str)->Option<(String,String,u16,String,bool)>{
    // returns scheme, host display for Host header/connect, port, path+query, is_tls
    let (scheme, rest)=url.split_once("://")?;
    let tls = scheme.eq_ignore_ascii_case("https");
    if !tls && !scheme.eq_ignore_ascii_case("http"){ return None; }
    let (authority, path) = match rest.find(|c| c=='/'||c=='?'){ Some(i)=>( &rest[..i], &rest[i..]), None=>(rest,"/") };
    // authority may contain userinfo@
    let hostport = match authority.rfind('@'){ Some(i)=>&authority[i+1..], None=>authority };
    let (host, port) = if hostport.starts_with('['){
        let end=hostport.find(']')?;
        let h=&hostport[..=end];
        let p=if hostport.len()>end+1 && hostport.as_bytes()[end+1]==b':' { hostport[end+2..].parse().unwrap_or(if tls{443}else{80}) } else if tls{443}else{80};
        (h.to_string(),p)
    } else if let Some(colon)=hostport.rfind(':'){
        (hostport[..colon].to_string(), hostport[colon+1..].parse().unwrap_or(if tls{443}else{80}))
    } else { (hostport.to_string(), if tls{443}else{80}) };
    let path = if path.is_empty(){ "/".to_string()} else if path.starts_with('?'){ format!("/{}",path)} else {path.to_string()};
    Some((scheme.to_lowercase(), host, port, path, tls))
}

fn fetch_once(url:&str, _referer:Option<&str>, cfg:&RetrieverConfig)->FetchResult{
    let start=Instant::now();
    let Some((_scheme,host,port,path,tls))=parse_url(url) else { return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); };
    // DNS + connect
    let host_for_dns = host.trim_start_matches('[').trim_end_matches(']');
    let addr_str=format!("{}:{}", host_for_dns, port);
    let addrs: Vec<std::net::SocketAddr> = match addr_str.to_socket_addrs(){ Ok(it)=>it.collect(), Err(_)=>return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()) };
    if addrs.is_empty(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
    let connect_deadline = cfg.connect_timeout.or(cfg.timeout);
    let mut stream_opt=None;
    for addr in &addrs {
        let s = match connect_deadline { Some(d)=> TcpStream::connect_timeout(addr, remaining(start,d)), None=> TcpStream::connect(addr) };
        match s { Ok(s)=>{stream_opt=Some(s); break;}, Err(_)=>continue }
    }
    let Some(mut stream)=stream_opt else { return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); };
    // timeouts for read/write: if total timeout set, use remaining
    let set_timeouts = |stream:&TcpStream|{
        if let Some(t)=cfg.timeout{ let r=remaining(start,t); let _=stream.set_read_timeout(Some(r)); let _=stream.set_write_timeout(Some(r)); }
        else { let _=stream.set_read_timeout(None); }
    };
    set_timeouts(&stream);

    // Build request
    let host_header = if (tls && port==443)||(!tls&&port==80){ host.clone()} else { format!("{}:{}",host,port)};
    let mut req=format!("GET {} HTTP/1.1\r\naccept: */*\r\nhost: {}\r\n", path, host_header);
    if let Some(r)=_referer{ req.push_str(&format!("referer: {}\r\n", r)); }
    req.push_str("connection: close\r\n\r\n");

    if tls {
        match tls_stream::connect(stream, &host, cfg) {
            Ok(mut tls)=>{
                if tls.write_all(req.as_bytes()).is_err(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
                return read_response_tls(&mut tls, url);
            }
            Err(_)=>{ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
        }
    } else {
        if stream.write_all(req.as_bytes()).is_err(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
        return read_response_tcp(&mut stream, url);
    }
}

fn remaining(start:Instant, total:Duration)->Duration{ total.checked_sub(start.elapsed()).unwrap_or(Duration::from_millis(1)) }

fn parse_response_head(head:&str)->(u16, Vec<(String,String)>){
    let mut lines=head.lines();
    let status_line=lines.next().unwrap_or("");
    let code:u16=status_line.split_whitespace().nth(1).and_then(|s|s.parse().ok()).unwrap_or(0);
    let mut headers=Vec::new();
