        fn write(&mut self, buf:&[u8])->std::io::Result<usize>{
            unsafe { let n=SSL_write(self.ssl, buf.as_ptr(), buf.len() as i32); if n<=0{ Err(std::io::Error::new(std::io::ErrorKind::BrokenPipe,"tls write")) } else {Ok(n as usize)} }
        }
        fn flush(&mut self)->std::io::Result<()>{ Ok(()) }
    }
