fn parse_url(url:&str)->Option<(String,String,u16,String,bool)>{
    // returns scheme, host display for Host header/connect, port, path+query, is_tls
    let (scheme, rest)=url.split_once("://")?;
    let tls = scheme.eq_ignore_ascii_case("https");
    if !tls && !scheme.eq_ignore_ascii_case("http"){ return None; }
    let (authority, path) = match rest.find(|c| c=='/'||c=='?'){ Some(i)=>( &rest[..i], &rest[i..]), None=>(rest,"/") };
