    let hostport = match authority.rfind('@'){ Some(i)=>&authority[i+1..], None=>authority };
    let (host, port) = if hostport.starts_with('['){
        let end=hostport.find(']')?;
        let h=&hostport[..=end];
        let p=if hostport.len()>end+1 && hostport.as_bytes()[end+1]==b':' { hostport[end+2..].parse().unwrap_or(if tls{443}else{80}) } else if tls{443}else{80};
