    Some((scheme.to_lowercase(), host, port, path, tls))
}

fn fetch_once(url:&str, _referer:Option<&str>, cfg:&RetrieverConfig)->FetchResult{
    let start=Instant::now();
    let Some((_scheme,host,port,path,tls))=parse_url(url) else { return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); };
    // DNS + connect
    let host_for_dns = host.trim_start_matches('[').trim_end_matches(']');
    let addr_str=format!("{}:{}", host_for_dns, port);
    let addrs: Vec<std::net::SocketAddr> = match addr_str.to_socket_addrs(){ Ok(it)=>it.collect(), Err(_)=>return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()) };
    if addrs.is_empty(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
    let connect_deadline = cfg.connect_timeout.or(cfg.timeout);
    let mut stream_opt=None;
    for addr in &addrs {
        let s = match connect_deadline { Some(d)=> TcpStream::connect_timeout(addr, remaining(start,d)), None=> TcpStream::connect(addr) };
        match s { Ok(s)=>{stream_opt=Some(s); break;}, Err(_)=>continue }
    }
    let Some(mut stream)=stream_opt else { return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); };
    // timeouts for read/write: if total timeout set, use remaining
    let set_timeouts = |stream:&TcpStream|{
        if let Some(t)=cfg.timeout{ let r=remaining(start,t); let _=stream.set_read_timeout(Some(r)); let _=stream.set_write_timeout(Some(r)); }
        else { let _=stream.set_read_timeout(None); }
