    set_timeouts(&stream);

    // Build request
    let host_header = if (tls && port==443)||(!tls&&port==80){ host.clone()} else { format!("{}:{}",host,port)};
    let mut req=format!("GET {} HTTP/1.1\r\naccept: */*\r\nhost: {}\r\n", path, host_header);
    if let Some(r)=_referer{ req.push_str(&format!("referer: {}\r\n", r)); }
    req.push_str("connection: close\r\n\r\n");

    if tls {
        match tls_stream::connect(stream, &host, cfg) {
            Ok(mut tls)=>{
                if tls.write_all(req.as_bytes()).is_err(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
