            Err(_)=>{ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
        }
    } else {
        if stream.write_all(req.as_bytes()).is_err(){ return FetchResult::Error("error sending request for url ({url})".into(), url.to_string()); }
        return read_response_tcp(&mut stream, url);
    }
}

