    let payload:Value = match output{
        "flag"=>{ let mut m=Map::new(); m.insert("valid".into(), Value::Bool(outcome.valid)); Value::Object(m) }
        "list"=>{ let mut details=Vec::new(); outcome.unit.flatten(&mut details); let mut m=Map::new(); m.insert("details".into(), Value::Array(details)); m.insert("valid".into(), Value::Bool(outcome.valid)); Value::Object(m) }
