import pathlib
p=pathlib.Path("src/uri.rs"); t=p.read_text()
old_start=t.find("pub fn validate_uri_ref(s:&str)->Result<(),String>{")
old_end=t.find("pub fn validate_uri_ref_err")
newfn='''pub fn validate_uri_ref(s:&str)->Result<(),String>{
    for (i,c) in s.char_indices(){
        let ok = match c {
            'A'..='Z'|'a'..='z'|'0'..='9'|'-'|'.'|'_'|'~'|':'|'/'|'?'|'#'|'['|']'|'@'|'!'|'$'|'&'|'\\''|'('|')'|'*'|'+'|','|';'|'='|'%' => true,
            _ => false,
        };
        if !ok {
            return Err(format!("unexpected character at index {}", i));
        }
    }
    let bytes=s.as_bytes(); let mut i=0;
    while i<bytes.len(){
        if bytes[i]==b'%'{
            if i+2>=bytes.len() || !(bytes[i+1] as char).is_ascii_hexdigit() || !(bytes[i+2] as char).is_ascii_hexdigit(){
                return Err(format!("invalid percent-encoded octet at index {}", i));
            }
            i+=3;
        } else { i+=1; }
    }
    // scheme / first-segment colon validation
    if s.starts_with(':'){ return Err("unexpected character at index 0".to_string()); }
    let first_delim = s.find(['/', '?', '#']).unwrap_or(s.len());
    if let Some(colon)=s[..first_delim].find(':'){
        let scheme=&s[..colon];
        if scheme.is_empty(){ return Err("unexpected character at index 0".to_string()); }
        let first=scheme.chars().next().unwrap();
        if !first.is_ascii_alphabetic(){ return Err("unexpected character at index 0".to_string()); }
        if !scheme.chars().all(|c|c.is_ascii_alphanumeric()||c=='+'||c=='-'||c=='.'){
            return Err(format!("unexpected character at index {}", colon));
        }
    }
    // authority validation
    let after_scheme = if let Some(colon)=s[..first_delim].find(':'){ &s[colon+1..] } else { s };
    if after_scheme.starts_with("//"){
        let auth_start = s.len()-after_scheme.len()+2;
        let rest=&after_scheme[2..];
        let auth_end_rel = rest.find(['/', '?', '#']).unwrap_or(rest.len());
        let authority=&rest[..auth_end_rel];
        let hostport = match authority.rfind('@'){ Some(at)=>&authority[at+1..], None=>authority };
        let hostport_start = auth_start + (authority.len()-hostport.len());
        if hostport.starts_with('['){
            match hostport.find(']'){
                None=>{ return Err(format!("unexpected character at index {}", if s.is_empty(){0}else{s.len()-1})); }
                Some(close)=>{
                    let after=&hostport[close+1..];
                    if !after.is_empty() && !after.starts_with(':'){
                        return Err(format!("unexpected character at index {}", hostport_start+close+1));
                    }
                    if let Some(colonrel)=after.find(':'){
                        let port=&after[colonrel+1..];
                        for (j,c) in port.char_indices(){
                            if !c.is_ascii_digit(){ return Err(format!("unexpected character at index {}", hostport_start+close+1+colonrel+1+j)); }
                        }
                    }
                    // validate IPv6 inside roughly
                    let inside=&hostport[1..close];
                    if !inside.is_empty() && inside.parse::<std::net::Ipv6Addr>().is_err() && !inside.starts_with('v'){
                        // fluent may report differently; ignore strict for now unless clearly invalid chars have been caught
                    }
                }
            }
        } else {
            if let Some(colon)=hostport.find(':'){
                let port=&hostport[colon+1..];
                for (j,c) in port.char_indices(){
                    if !c.is_ascii_digit(){ return Err(format!("unexpected character at index {}", hostport_start+colon+1+j)); }
                }
            }
        }
    }
    Ok(())
}

'''
