import sys,random,json,os
sys.path.insert(0,"/tmp"); from harness import w
import subprocess
ORIG="/workspace/orig.bin"; NEW="/workspace/executable"
random.seed(int(sys.argv[1])); N=int(sys.argv[2])
def rand_schema(depth=0):
    if depth>3: return random.choice([True,False,{"type":"string"}])
    k=random.randint(0,7)
    if k==0: return {"type":random.choice(["string","integer","number","object","array","boolean","null"])}
    if k==1: return {"properties":{random.choice(["a","b"]):rand_schema(depth+1)}}
    if k==2: return {random.choice(["allOf","anyOf","oneOf"]):[rand_schema(depth+1) for _ in range(random.randint(1,2))]}
    if k==3: return {"items":rand_schema(depth+1)} if random.random()<0.5 else {"prefixItems":[rand_schema(depth+1)]}
    if k==4: return {random.choice(["minimum","minLength","maxLength","minItems","minProperties"]):random.randint(0,3)}
    if k==5: return {"required":[random.choice(["a","b"])], "properties":{"a":rand_schema(depth+1)}}
    if k==6: return {"$defs":{"x":rand_schema(depth+1)}, "$ref":random.choice(["#/$defs/x","#","#/missing"])}
    return {"not":rand_schema(depth+1)} if random.random()<0.5 else {"if":rand_schema(depth+1),"then":rand_schema(depth+1),"else":rand_schema(depth+1)}
def rand_inst(depth=0):
    c=random.randint(0,6 if depth<2 else 4)
    return [0,1,"a","abc",True,None,1.5][c] if c<7 and depth>=2 else ([random.randint(0,3),"a",1.5][random.randint(0,2)] if depth>=2 else ([rand_inst(depth+1) for _ in range(2)] if c==5 else {k:rand_inst(depth+1) for k in ["a","b"][:random.randint(0,2)]} if c==6 else [0,1,"a","abc",True][c]))
fails=0
for n in range(N):
    s=rand_schema(); i=rand_inst(); out=random.choice(["text","flag","list"])
    args=[]
    if out!="text": args+=["--output",out]
    sp=w("s.json",s); ip=w("i.json",i); args+=[sp,"-i",ip]
    try: ro=subprocess.run([ORIG]+args,capture_output=True,text=True,timeout=5)
    except Exception as e: print("orig timeout",s,i); continue
    try: rn=subprocess.run([NEW]+args,capture_output=True,text=True,timeout=5)
    except Exception as e: print("NEW timeout/panic?",s,i,out,e); fails+=1; continue
    if (ro.returncode,ro.stdout,ro.stderr)!=(rn.returncode,rn.stdout,rn.stderr):
        fails+=1; print("MISMATCH",json.dumps(s),json.dumps(i),out); print(" orig",ro.returncode,repr(ro.stdout[:1500]),repr(ro.stderr[:500])); print(" new",rn.returncode,repr(rn.stdout[:1500]),repr(rn.stderr[:500])); sys.stdout.flush()
        if fails>10: break
print("fails",fails,"/",N)
